(function () {
window.AINOW = window.AINOW || {};
var __exports = AINOW['data/data-legal'] = AINOW['data/data-legal'] || {};
const legalPrompts = [
  {"id":"leg-1","title":"SaaS Enterprise BAA Review Memo","prompt":"You are in-house counsel at a 300-person US healthcare SaaS company about to sign a Business Associate Agreement (BAA) with a new cloud infrastructure vendor. Draft a BAA review memo covering: the five most critical HIPAA-required provisions and whether each is present and adequate, specific red flags in subcontractor provisions that could expose your company to downstream breach liability, the permitted use and disclosure limitations you need the vendor to accept, the breach notification timeline clause (HIPAA requires 60 days — vendors often push for 90), and the termination and data destruction obligations. Flag any clauses that would be non-starters and suggest specific alternative language for each. Format as a legal review memo with a risk rating of High/Medium/Low for each issue. For educational purposes — consult a qualified attorney for legal advice.","tags":["hipaa","healthcare","contracts","saas"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},

  {"id":"leg-2","title":"SaaS MSA Liability Cap Negotiation","prompt":"You are a corporate attorney at a mid-size law firm specializing in SaaS vendor contracts for enterprise clients. Your client, a 500-person financial services firm, is negotiating a Master Services Agreement with a major CRM vendor. The vendor's standard template caps liability at three months of fees paid. Analyze the liability cap clause, explain why this is inadequate for a financial services context, draft alternative language proposing a 12-month fee cap with carve-outs for data breaches, IP indemnification, and willful misconduct, and explain the negotiating leverage your client has as an enterprise buyer. Provide the redlined alternative clause in standard legal format. [Paste the contract clause or document excerpt] For educational purposes — consult a qualified attorney for legal advice.","tags":["saas","contracts","liability","negotiation"],"author":"AINOW","created":"2024-02-15T10:05:00Z","featured":false},

  {"id":"leg-3","title":"Mutual NDA for AI Technology Partnership","prompt":"You are a transactional attorney drafting a mutual non-disclosure agreement for two AI technology companies exploring a potential joint development partnership. One party is a US-based startup with proprietary training data; the other is a UK-based enterprise software company. Draft a mutual NDA that covers: a precise definition of Confidential Information that explicitly includes model weights, training datasets, and fine-tuning methodologies; exclusions for residual knowledge in unaided human memory (the so-called 'residuals clause' common in tech NDAs); a five-year term with perpetual protection for trade secrets; a cross-border data transfer clause compliant with UK GDPR post-Brexit; governing law selection and why Delaware law is preferable; and injunctive relief provisions. Explain the reasoning behind each major drafting choice. For educational purposes — consult a qualified attorney for legal advice.","tags":["nda","ip","uk-gdpr","ai","contracts"],"author":"AINOW","created":"2024-02-15T10:10:00Z","featured":false},

  {"id":"leg-4","title":"SaaS Agreement Clause-by-Clause Audit","prompt":"You are a senior associate at a technology transactions practice reviewing a SaaS subscription agreement on behalf of a Series B startup that will be the customer. Conduct a clause-by-clause audit of the agreement excerpt below, identifying: auto-renewal traps and notice window problems, data ownership and portability gaps, acceptable use policy overreach that could allow vendor to terminate without cause, limitation of liability exclusions that gut the cap, and audit rights provisions the vendor can use intrusively. For each identified issue, state the risk level (High/Medium/Low), explain the business impact, and draft replacement language. [Paste the contract clause or document excerpt] For educational purposes — consult a qualified attorney for legal advice.","tags":["saas","contracts","audit","startup"],"author":"AINOW","created":"2024-02-15T10:15:00Z","featured":false},

  {"id":"leg-5","title":"Professional Services Agreement for Consulting Firm","prompt":"You are a contracts attorney drafting a Professional Services Agreement for a management consulting firm that will deliver digital transformation projects to Fortune 500 clients. The engagements typically run 6-18 months and involve the firm's proprietary frameworks. Draft the agreement covering: a precise statement of work structure with acceptance criteria to avoid scope creep disputes, a background IP versus foreground IP distinction that protects the firm's proprietary methodologies, a work-for-hire carve-out limited strictly to client-specific deliverables, a change order mechanism with fee adjustment rights, a consequential damages waiver with explicit carve-outs, and a benchmarking and reference prohibition. Explain why each provision matters in a consulting context. For educational purposes — consult a qualified attorney for legal advice.","tags":["consulting","contracts","ip","services"],"author":"AINOW","created":"2024-02-15T10:20:00Z","featured":false},

  {"id":"leg-6","title":"Force Majeure Clause for Supply Chain Contracts","prompt":"You are a commercial contracts attorney advising a US-based electronics manufacturer on updating its standard supplier agreements after COVID-19 and semiconductor shortage disruptions exposed gaps in existing force majeure language. Redraft the force majeure clause to explicitly address: pandemic and public health emergency declarations at federal and state levels, export control restrictions and sanctions-triggered supply disruptions, semiconductor allocation shortfalls caused by foundry capacity constraints, ransomware and critical infrastructure cyberattacks affecting supplier operations, and the distinction between excuse of performance versus suspension of performance with resumption obligations. Include a notice and mitigation protocol with specific deadlines. Explain how courts in New York and California have interpreted force majeure differently since 2020. For educational purposes — consult a qualified attorney for legal advice.","tags":["contracts","supply-chain","force-majeure","commercial"],"author":"AINOW","created":"2024-02-15T10:25:00Z","featured":false},

  {"id":"leg-7","title":"Data Processing Agreement Under GDPR Article 28","prompt":"You are a privacy attorney at a European law firm drafting a Data Processing Agreement (DPA) between a German e-commerce company (Controller) and a US-based email marketing platform (Processor). The DPA must comply with GDPR Article 28 and incorporate the EU Standard Contractual Clauses (Module 2: Controller to Processor) for the US data transfer. Draft the core DPA provisions covering: the specific subject matter, nature, purpose, and duration of processing; the full enumeration of Technical and Organisational Measures (TOMs) required under Article 32; sub-processor authorization procedures and the 30-day objection right; the data breach notification obligation and the 72-hour chain-of-notification requirement; data return and deletion obligations on termination; and audit rights. Flag any provisions the US processor is likely to resist and suggest compromise language. For educational purposes — consult a qualified attorney for legal advice.","tags":["gdpr","privacy","dpa","eu","contracts"],"author":"AINOW","created":"2024-02-15T10:30:00Z","featured":false},

  {"id":"leg-8","title":"Enterprise Software License Agreement Review","prompt":"You are in-house counsel at a 2,000-employee manufacturing company reviewing a proposed enterprise software license agreement from an ERP vendor before a $3M multi-year commitment. Review the agreement excerpt below and analyze: the scope of the license grant and whether it covers all intended use cases including subsidiaries and contractors, audit rights provisions and the financial exposure your company faces if the vendor conducts a true-up audit, source code escrow adequacy for business continuity if the vendor is acquired or goes bankrupt, the SLA structure and whether service credits are the sole remedy for outages, and assignment provisions in the context of your company's pending acquisition. Provide a negotiation priority list ranked by financial and operational risk. [Paste the contract clause or document excerpt] For educational purposes — consult a qualified attorney for legal advice.","tags":["software","license","enterprise","contracts"],"author":"AINOW","created":"2024-02-15T10:35:00Z","featured":false},

  {"id":"leg-9","title":"API Terms of Service for Developer Platform","prompt":"You are a technology attorney drafting Terms of Service for a B2B API platform that provides financial data aggregation services to fintech developers. The platform handles bank account data subject to both CCPA and GLBA. Draft the API Terms covering: a license grant limited to the specific use case approved during onboarding with explicit prohibited uses, data use restrictions that comply with GLBA's Safeguards Rule and CCPA's service provider exception, rate limiting and throttling provisions with the right to suspend for abuse, intellectual property ownership of derived data and model outputs generated using the API, indemnification obligations for developers who violate the prohibited use list, and a unilateral amendment right with 30-day notice for material changes. Explain the tension between GLBA and CCPA compliance in this context. For educational purposes — consult a qualified attorney for legal advice.","tags":["api","fintech","ccpa","glba","contracts"],"author":"AINOW","created":"2024-02-15T10:40:00Z","featured":false},

  {"id":"leg-10","title":"Termination for Convenience vs. Cause Analysis","prompt":"You are a commercial litigation attorney advising a software development agency whose major client has just sent a notice purporting to terminate their $2M annual services contract 'for cause' due to alleged project delays. The contract has both a termination-for-cause provision requiring a 30-day cure period and a termination-for-convenience provision allowing termination with 90 days notice and a wind-down fee. Analyze the legal distinction between the two termination rights, what the client must prove to validly terminate for cause versus convenience, what damages your client is owed under each scenario, how courts in Delaware handle wrongful termination of commercial contracts, and what your immediate next steps should be including preservation of evidence and response letter strategy. [Paste the contract clause or document excerpt] For educational purposes — consult a qualified attorney for legal advice.","tags":["contracts","termination","litigation","commercial"],"author":"AINOW","created":"2024-02-15T10:45:00Z","featured":false},

  {"id":"leg-11","title":"California At-Will Employment Offer Letter Review","prompt":"You are an employment attorney at a California-based law firm advising a Series A startup preparing to hire its first 10 employees. Review the proposed offer letter template and identify: language that inadvertently creates an implied contract undermining at-will employment status, required California-specific disclosures including wage theft prevention act notices and pay transparency requirements under SB 1162, problematic equity grant language that overpromises vesting without proper qualification, confidentiality and IP assignment clause adequacy under California Labor Code Section 2870 (which limits what employers can claim), and arbitration agreement enforceability issues after California's ongoing legislative hostility to mandatory arbitration. Rewrite the problematic clauses. [Paste your draft agreement] For educational purposes — consult a qualified attorney for legal advice.","tags":["employment","california","offer-letter","startup"],"author":"AINOW","created":"2024-02-15T10:50:00Z","featured":false},

  {"id":"leg-12","title":"Non-Compete Agreement Enforceability Analysis","prompt":"You are an employment attorney analyzing the enforceability of a non-compete agreement that a technology company wants to require all software engineers to sign as a condition of employment. The company has offices in Texas, Illinois, and Washington state. Conduct a multi-jurisdiction enforceability analysis covering: Texas's 'Covenant Not to Compete Act' and the legitimate business interest and reasonableness requirements, Illinois's Freedom to Work Act and its income thresholds that limit non-compete enforcement, Washington's near-complete ban on non-competes for employees earning under $100,000, the FTC's 2024 rule on non-competes and its current litigation status, and alternative protections the company should use instead (non-solicitation, NDA, IP assignment). Draft a jurisdiction-specific approach for each state. For educational purposes — consult a qualified attorney for legal advice.","tags":["employment","non-compete","multi-jurisdiction","hr"],"author":"AINOW","created":"2024-02-15T10:55:00Z","featured":false},

  {"id":"leg-13","title":"WARN Act Compliance for Layoffs","prompt":"You are an employment attorney advising the HR department of a 650-person technology company that is planning a workforce reduction affecting approximately 120 employees across its California and New York offices, with the reductions occurring over 45 days. Analyze the federal WARN Act obligations (60-day advance notice requirement), California's mini-WARN Act (Cal-WARN) which has a lower 75-employee threshold and 60-day notice requirement, New York's WARN Act equivalents, whether the 'faltering company' or 'unforeseeable business circumstances' exceptions apply given the company's financial situation, what notices must be sent and to whom (employees, unions if any, state agencies), and the liability exposure for non-compliance including back pay and benefits for each day of violation. Draft a WARN Act compliance calendar. For educational purposes — consult a qualified attorney for legal advice.","tags":["employment","warn-act","layoffs","california"],"author":"AINOW","created":"2024-02-15T11:00:00Z","featured":false},

  {"id":"leg-14","title":"Employee Handbook Workplace Investigation Policy","prompt":"You are an employment attorney drafting the Workplace Investigation Policy section of an employee handbook for a 200-person company operating in California and Texas. The policy must cover: the scope of investigations including harassment, discrimination, retaliation, and policy violations under Title VII and California's FEHA; investigation initiation triggers and who is authorized to investigate; confidentiality obligations and the tension with the NLRA Section 7 right to discuss working conditions; documentation requirements and file retention; interim measures including administrative leave and the legal risks of overusing it; the rights of the accused versus the reporting party; and the anti-retaliation protections that attach the moment a complaint is made. Include sample language for the investigation notice letter. For educational purposes — consult a qualified attorney for legal advice.","tags":["employment","hr","investigations","california"],"author":"AINOW","created":"2024-02-15T11:05:00Z","featured":false},

  {"id":"leg-15","title":"Independent Contractor Misclassification Risk Assessment","prompt":"You are a labor and employment attorney conducting a worker classification risk assessment for a gig-economy platform that uses 800 independent contractors to deliver services in California, New York, and New Jersey. Analyze the misclassification risk using: California's ABC Test under AB5 and the specific industry exemptions available, New York's economic reality test and the Department of Labor enforcement priorities, New Jersey's ABC Test and the recent aggressive enforcement posture, IRS 20-factor control test for federal tax purposes, and the NLRA joint-employer standard under the NLRB's 2023 rule. Quantify the exposure if the workers are reclassified (back taxes, benefits, penalties) and recommend a compliance strategy including whether to pursue reclassification, seek an exemption, or restructure the business model. For educational purposes — consult a qualified attorney for legal advice.","tags":["employment","gig-economy","misclassification","california"],"author":"AINOW","created":"2024-02-15T11:10:00Z","featured":false},

  {"id":"leg-16","title":"Severance Agreement and ADEA Waiver","prompt":"You are an employment attorney drafting a severance agreement and general release for a technology company offering severance to a group of 15 employees being laid off, several of whom are over 40 years old. Draft the agreement ensuring: full compliance with the Older Workers Benefit Protection Act (OWBPA) requirements for a valid ADEA waiver including the 45-day consideration period for group layoffs, the 7-day revocation right and why you cannot waive it, the required statistical disclosure about the decisional unit showing ages and job titles of those selected and not selected, a broad release of claims with proper carve-outs for EEOC charges and workers' compensation, COBRA notification obligations, and the return of company property and confidentiality obligations. Explain what happens if any OWBPA requirement is omitted. For educational purposes — consult a qualified attorney for legal advice.","tags":["employment","adea","severance","hr"],"author":"AINOW","created":"2024-02-15T11:15:00Z","featured":false},

  {"id":"leg-17","title":"Pay Equity Audit Legal Framework","prompt":"You are an employment attorney advising a 400-person company in Illinois that wants to conduct a proactive pay equity audit before Illinois's Equal Pay Act registration requirements trigger a compliance review. Outline the attorney-client privilege strategy for protecting the audit under Upjohn principles, the statistical methodology for identifying unexplained pay gaps by gender and race using regression analysis, how Illinois's Equal Pay Act of 2021 defines 'substantially similar work' differently from the federal Equal Pay Act, what remediation steps create legal risk if disclosed prematurely, the interaction between the pay equity audit and NLRA Section 7 rights of employees to discuss pay, and how to structure the audit findings report to minimize litigation risk if the document is ever subpoenaed. For educational purposes — consult a qualified attorney for legal advice.","tags":["employment","pay-equity","illinois","compliance"],"author":"AINOW","created":"2024-02-15T11:20:00Z","featured":false},

  {"id":"leg-18","title":"Remote Work Policy and Multi-State Tax Nexus","prompt":"You are an employment attorney and tax counsel advising a Delaware-incorporated technology company whose 300 employees have scattered to 22 states following a shift to permanent remote work. Draft a Remote Work Policy that addresses: the approval process for remote work and how it intersects with ADA reasonable accommodation requests, state income tax withholding obligations triggered when employees work remotely from states where the company has no office, the concept of 'convenience of the employer' doctrine used by New York to tax remote workers, corporate income tax nexus and apportionment consequences of remote workers creating physical presence in new states, workers' compensation coverage requirements for remote workers in each state, and the documentation required to defend against state tax audits. Flag the five highest-risk states for remote worker tax nexus. For educational purposes — consult a qualified attorney for legal advice.","tags":["employment","remote-work","tax","multi-state"],"author":"AINOW","created":"2024-02-15T11:25:00Z","featured":false},

  {"id":"leg-19","title":"Trade Secret Protection for Departing Employee","prompt":"You are an employment attorney advising a SaaS company whose head of sales just resigned to join a direct competitor, taking with her a copy of the company's customer database, pricing models, and strategic roadmap documents copied to a personal device two weeks before her departure. Outline the immediate legal response covering: an emergency TRO application under the Defend Trade Secrets Act (DTSA) and the requirements for ex parte relief, the elements of a DTSA claim and what the company must prove to establish trade secret misappropriation, forensic evidence preservation steps the company must take immediately, a litigation hold notice and what ESI must be preserved, cease and desist letter strategy and the risks of overreaching, potential claims against the new employer for tortious interference and aiding misappropriation, and the company's obligations to notify customers if their data was taken. For educational purposes — consult a qualified attorney for legal advice.","tags":["employment","trade-secrets","dtsa","litigation"],"author":"AINOW","created":"2024-02-15T11:30:00Z","featured":false},

  {"id":"leg-20","title":"Workplace Accommodation Interactive Process","prompt":"You are an employment attorney drafting a step-by-step interactive process protocol for a company receiving an ADA accommodation request from an employee with a newly diagnosed anxiety disorder who is requesting permanent remote work as an accommodation. The protocol must cover: the legal trigger for initiating the interactive process and the timeline to avoid a failure-to-accommodate claim, what medical documentation the company can lawfully request under the ADA and HIPAA, the legal standard for 'undue hardship' and how courts have ruled on remote work as an ADA accommodation post-pandemic, how to document the interactive process to defeat a later failure-to-accommodate claim, the intersection with FMLA leave if the condition also qualifies, and how to handle the situation if the direct manager opposes remote work for a legitimate business reason. Include a documentation checklist. For educational purposes — consult a qualified attorney for legal advice.","tags":["employment","ada","accommodation","hr"],"author":"AINOW","created":"2024-02-15T11:35:00Z","featured":false},

  {"id":"leg-21","title":"Delaware LLC Operating Agreement for VC-Backed Startup","prompt":"You are a corporate attorney at a startup-focused law firm advising two co-founders who are converting their LLC to a Delaware C-Corporation ahead of a Series A raise, but want to understand their operating agreement rights before conversion. Analyze the operating agreement for: the decision-making provisions that give one founder veto rights over major decisions and how those interact with fiduciary duties, drag-along provisions and whether they require consent from members holding a specified percentage, the buyout mechanism for a departing founder including the price-setting process and whether it adequately protects a minority member, whether the capital contribution obligations create personal liability risk, how profits interests issued to employees will be treated on conversion versus equity grants, and what the Delaware Court of Chancery's recent jurisprudence says about LLC member fiduciary duties. [Paste your draft agreement] For educational purposes — consult a qualified attorney for legal advice.","tags":["corporate","llc","delaware","startup"],"author":"AINOW","created":"2024-02-15T11:40:00Z","featured":false},

  {"id":"leg-22","title":"Series A Term Sheet Negotiation Guide","prompt":"You are a corporate attorney advising a seed-stage SaaS startup that has received a Series A term sheet from a leading venture capital firm. Walk through each major economic and control term in the term sheet explaining: the difference between pre-money and post-money valuation and how the option pool shuffle artificially dilutes founders before the investment closes, participating preferred versus non-participating preferred and the liquidation preference multiple the founders should accept versus reject, pro-rata rights and how they compound investor control across future rounds, protective provisions and which ones represent standard market practice versus overreach by the investor, board composition proposals and the importance of maintaining founder control at the board level, and information rights and their interaction with confidentiality. Flag the three terms that have the most significant long-term financial impact on founder economics. [Paste the contract clause or document excerpt] For educational purposes — consult a qualified attorney for legal advice.","tags":["corporate","venture-capital","startup","term-sheet"],"author":"AINOW","created":"2024-02-15T11:45:00Z","featured":false},

  {"id":"leg-23","title":"M&A Due Diligence Legal Risk Report","prompt":"You are M&A counsel conducting legal due diligence on a $45M acquisition of a 80-person cybersecurity software company. Draft a due diligence legal risk report covering: IP ownership chain-of-title issues including whether all founders and early contractors signed IP assignment agreements, litigation and regulatory risk including any unresolved EEOC charges or government contracts compliance issues under FAR/DFARS, material contract assignment restrictions and change-of-control clauses in top-10 customer agreements that could trigger termination rights, data privacy compliance posture including any CCPA or GDPR enforcement history or outstanding DPA deficiencies, equity capitalization table accuracy and whether all option grants were properly authorized and documented, and key-person dependency risks in the founding team. Rate each risk area High/Medium/Low and recommend representations and warranties that must appear in the purchase agreement. For educational purposes — consult a qualified attorney for legal advice.","tags":["ma","corporate","due-diligence","acquisition"],"author":"AINOW","created":"2024-02-15T11:50:00Z","featured":false},

  {"id":"leg-24","title":"Corporate Governance Bylaws for Public Company Board","prompt":"You are a securities and governance attorney advising a company preparing for an IPO on NASDAQ. Draft the corporate governance provisions of the bylaws covering: director independence standards under NASDAQ Rule 5605 and the composition requirements for audit, compensation, and nominating/governance committees, the advance notice bylaw for shareholder nominations and how to set the notice window to balance shareholder rights against hostile activist campaigns, the majority voting standard for director elections versus plurality voting and the resignation policy for directors who fail to receive a majority, classified board structure considerations and the tradeoffs in Delaware after recent Court of Chancery scrutiny, forum selection bylaw designating Delaware as the exclusive forum for derivative suits and the federal district court for Securities Act claims, and D&O indemnification provisions and the mandatory versus permissive indemnification distinction under DGCL Section 145. For educational purposes — consult a qualified attorney for legal advice.","tags":["corporate","governance","ipo","nasdaq"],"author":"AINOW","created":"2024-02-15T11:55:00Z","featured":false},

  {"id":"leg-25","title":"Shareholder Dispute Resolution in a Closely Held Corporation","prompt":"You are a corporate litigation attorney advising a minority shareholder who holds 30% of a Delaware C-Corporation and believes the majority shareholders are engaging in oppressive conduct including self-dealing transactions, exclusion from management, and elimination of dividends while paying excessive salaries to themselves. Analyze the available legal remedies including: Delaware's standard for shareholder oppression and why it is less protective than many states, derivative suit requirements under Delaware Rule 23.1 including the demand requirement and the business judgment rule defense, direct versus derivative claim analysis for the self-dealing transactions, the availability of judicial dissolution under DGCL Section 273 for a 50/50 deadlock versus Section 226 for a non-deadlocked corporation, appraisal rights and when they are available, and the litigation strategy for extracting a buyout at fair value. [Describe the legal situation or dispute] For educational purposes — consult a qualified attorney for legal advice.","tags":["corporate","shareholder","litigation","delaware"],"author":"AINOW","created":"2024-02-15T12:00:00Z","featured":false},

  {"id":"leg-26","title":"Nonprofit Board Governance and Conflict of Interest Policy","prompt":"You are a nonprofit corporate attorney advising the board of a 501(c)(3) charitable organization that has grown to $15M in annual revenue and is facing IRS scrutiny after a whistleblower complaint about board member self-dealing. Draft a comprehensive conflict of interest policy compliant with IRS Form 990 Schedule O disclosure requirements covering: the definition of a disqualifying conflict under IRC Section 4958 intermediate sanctions, the required recusal and abstention procedures for interested transactions, the independent board approval process for compensation of officers and related party transactions, the documentation required to establish the rebuttable presumption of reasonableness for compensation decisions, how to handle a board member who refuses to recuse despite a conflict, and the clawback mechanism for excess benefit transactions. Include a sample annual conflict disclosure questionnaire. For educational purposes — consult a qualified attorney for legal advice.","tags":["nonprofit","governance","irs","corporate"],"author":"AINOW","created":"2024-02-15T12:05:00Z","featured":false},

  {"id":"leg-27","title":"SPAC Merger De-SPAC Transaction Analysis","prompt":"You are a securities attorney advising the target company in a proposed de-SPAC merger with a publicly traded blank check company. Analyze the key legal risks and obligations for the target company's management team covering: the securities law disclosure obligations for the proxy statement or S-4 registration statement including the heightened scrutiny of financial projections, the fiduciary duties of the SPAC sponsor and potential liability for the 'promote' structure, the lock-up and earnout provisions in the merger agreement and their accounting treatment under ASC 815, the redemption right exercise by SPAC shareholders and the minimum cash condition threshold, the D&O tail insurance requirements given the change in public company status, and the SEC's 2023 de-SPAC rules that eliminated the safe harbor for SPAC projections. Rate each risk area and identify the deal-breaker conditions for the target. For educational purposes — consult a qualified attorney for legal advice.","tags":["corporate","spac","securities","ma"],"author":"AINOW","created":"2024-02-15T12:10:00Z","featured":false},

  {"id":"leg-28","title":"Joint Venture Agreement Structure for Technology Commercialization","prompt":"You are a corporate attorney structuring a joint venture between a US university technology transfer office and a private equity-backed life sciences company to commercialize a patented RNA delivery platform. Draft the joint venture agreement framework covering: the entity structure (LLC versus corporation) and why a Delaware LLC with a detailed operating agreement is preferred for tax flexibility, the IP contribution agreement and license-back provisions that let the university retain academic use rights, the governance structure for a 50/50 JV including tie-breaking mechanisms and reserved matters requiring unanimous consent, the capital call mechanism and dilution consequences for a party that fails to fund, the exit provisions including drag-along, tag-along, and put/call options with a fair market value appraisal mechanism, and the Bayh-Dole Act compliance requirements for federally funded university IP. For educational purposes — consult a qualified attorney for legal advice.","tags":["corporate","joint-venture","ip","university"],"author":"AINOW","created":"2024-02-15T12:15:00Z","featured":false},

  {"id":"leg-29","title":"409A Valuation and Stock Option Plan Compliance","prompt":"You are a corporate attorney advising a pre-IPO technology company whose board is about to approve a new round of stock option grants following a Series B financing. Analyze the Section 409A compliance requirements for the option grants covering: why options granted below fair market value create immediate income recognition and a 20% excise tax penalty for the employee, the IRS safe harbor methods for establishing FMV including the 409A independent appraisal requirement, the 12-month lookback rule and when you can rely on an existing 409A valuation versus when a new one is required, the difference between ISOs and NSOs and the alternative minimum tax trap for ISO holders, the mechanics of an option exercise and early exercise with an 83(b) election, and what happens to unvested options in an M&A transaction under single-trigger versus double-trigger acceleration provisions. For educational purposes — consult a qualified attorney for legal advice.","tags":["corporate","equity","tax","startup"],"author":"AINOW","created":"2024-02-15T12:20:00Z","featured":false},

  {"id":"leg-30","title":"Delaware Fiduciary Duty Analysis for Board Decision","prompt":"You are a Delaware corporate law specialist advising a board of directors considering a sale of the company at a significant premium to current market price, but the CEO believes the company is worth substantially more if it executes its five-year strategic plan. Analyze the fiduciary duties applicable to this decision covering: the business judgment rule and how it protects board decisions made on an informed basis in good faith, when Revlon duties are triggered requiring the board to maximize current shareholder value, the Unocal enhanced scrutiny standard for defensive measures adopted to block the bid, the role of a special committee of independent directors and why investment banking fairness opinions are necessary, the MFW framework requirements for controlling shareholder transactions, and the specific disclosure obligations to shareholders under Corwin doctrine. Advise the board on the process it must follow to minimize litigation exposure from a shareholder vote. For educational purposes — consult a qualified attorney for legal advice.","tags":["corporate","delaware","fiduciary","ma"],"author":"AINOW","created":"2024-02-15T12:25:00Z","featured":false},

  {"id":"leg-31","title":"Software Patent Application Strategy for AI Product","prompt":"You are a patent attorney at a firm specializing in technology intellectual property advising a startup that has developed a novel machine learning algorithm for real-time fraud detection in payment processing. Develop a patent strategy covering: the Alice/Mayo subject matter eligibility framework and how to draft claims that survive a Section 101 rejection by anchoring the abstract idea to a specific technical improvement, the claim drafting strategy for method claims, system claims, and CRM claims to maximize prosecution and litigation value, the prior art landscape analysis needed before filing including how to search arXiv and academic publications that may constitute anticipatory prior art, the international filing strategy including PCT application timing and key jurisdictions (US, EU, China, Japan), trade secret protection as an alternative or complement to patenting the core algorithm, and the provisional application strategy and the 12-month conversion deadline. For educational purposes — consult a qualified attorney for legal advice.","tags":["ip","patents","ai","technology"],"author":"AINOW","created":"2024-02-15T12:30:00Z","featured":false},

  {"id":"leg-32","title":"Trademark Clearance and Registration Strategy","prompt":"You are a trademark attorney advising a consumer fintech startup that has developed a brand name and logo for its mobile payment app and wants to launch nationally in 60 days. Conduct a trademark clearance and registration analysis covering: the comprehensive clearance search methodology including USPTO TESS, state trademark registries, common law use via Google and social media, and domain name registrations, the likelihood of confusion analysis under the DuPont factors and which factors are most critical for financial services marks, the strength of the proposed mark on the spectrum from generic to fanciful and why this matters for registration and enforcement, the Madrid Protocol international registration strategy for planned EU and UK expansion, the use-in-commerce versus intent-to-use application choice and the Statement of Use filing obligations, and the specimen requirements for financial services marks in Class 36. Flag any near-conflicts found and recommend whether to proceed, modify, or abandon the mark. For educational purposes — consult a qualified attorney for legal advice.","tags":["ip","trademark","brand","fintech"],"author":"AINOW","created":"2024-02-15T12:35:00Z","featured":false},

  {"id":"leg-33","title":"Copyright Infringement Analysis for AI Training Data","prompt":"You are an intellectual property attorney analyzing the copyright implications of a generative AI company that scraped publicly available web content including news articles, books, and images to train its large language model. Analyze: the application of the fair use four-factor test to AI training data ingestion under the most recent federal court decisions including Andersen v. Stability AI and the New York Times v. OpenAI litigation, whether the output of the model constitutes derivative works that infringe the training data, the EU AI Act's transparency obligations regarding training data sources and the TDM exception under EU copyright law, the practical risk of statutory damages exposure given the scale of the ingestion, the licensing landscape and whether licensing training data from major publishers is legally required or merely commercially advisable, and the steps the company should take now to reduce litigation exposure. [Describe the legal situation or dispute] For educational purposes — consult a qualified attorney for legal advice.","tags":["ip","copyright","ai","litigation"],"author":"AINOW","created":"2024-02-15T12:40:00Z","featured":false},

  {"id":"leg-34","title":"Trade Secret Protection Program for SaaS Company","prompt":"You are an intellectual property attorney designing a comprehensive trade secret protection program for a 150-person SaaS company whose core competitive advantage is its proprietary pricing algorithm and customer churn prediction model. The program must satisfy the 'reasonable measures' requirement under the Defend Trade Secrets Act (DTSA). Design the program covering: the trade secret identification and inventory process including how to categorize and document what is protected and why, physical and digital access controls required to demonstrate reasonable measures, employee onboarding and offboarding protocols including IP assignment agreements and exit interviews, the computer and system access monitoring program and its interaction with employee privacy expectations, customer and partner NDA enforcement including how to track execution and maintain a register, and the litigation readiness checklist for filing a DTSA emergency injunction within 24 hours of suspected misappropriation. For educational purposes — consult a qualified attorney for legal advice.","tags":["ip","trade-secrets","dtsa","saas"],"author":"AINOW","created":"2024-02-15T12:45:00Z","featured":false},

  {"id":"leg-35","title":"Open Source License Compliance for Enterprise Software","prompt":"You are an intellectual property attorney conducting an open source license compliance review for a software company preparing for acquisition. The company's product incorporates 47 open source components including components licensed under GPL v2, LGPL, MIT, Apache 2.0, and AGPL v3. Analyze: the copyleft contamination risk from GPL and AGPL components and whether the company's proprietary code has been combined in a way that triggers the derivative works obligation to open source its code, the specific technical triggering conditions for AGPL v3's network use provision and whether the company's SaaS delivery model triggers it, the patent grant provisions in Apache 2.0 and their interaction with any company patent filings, the notice and attribution obligations the company has likely failed to comply with and the cost of remediation, the acquirer's due diligence questions the company needs to be prepared to answer, and a remediation priority list. [Paste the contract clause or document excerpt] For educational purposes — consult a qualified attorney for legal advice.","tags":["ip","open-source","software","ma"],"author":"AINOW","created":"2024-02-15T12:50:00Z","featured":false},

  {"id":"leg-36","title":"DMCA Takedown Notice Strategy and Safe Harbor Defense","prompt":"You are a copyright attorney advising an online marketplace platform that hosts user-generated content and has received a batch of 200 DMCA takedown notices from a major music publisher claiming that user-uploaded videos contain infringing music. Analyze the DMCA Section 512 safe harbor requirements the platform must satisfy covering: the four prongs of the Section 512(c) safe harbor including the lack of actual knowledge standard and the 'red flag' knowledge doctrine, the designated agent registration requirement with the Copyright Office and why its absence completely eliminates the safe harbor, the expeditious takedown obligation and what timeline courts have found acceptable, the counter-notification procedure and the risks of restoring content if the copyright holder then files suit, the repeat infringer policy requirement and what constitutes an adequate policy under Viacom v. YouTube, and whether the platform's recommendation algorithm creates direct liability exposure beyond the safe harbor. For educational purposes — consult a qualified attorney for legal advice.","tags":["ip","copyright","dmca","platform"],"author":"AINOW","created":"2024-02-15T12:55:00Z","featured":false},

  {"id":"leg-37","title":"GDPR Compliance Gap Analysis for US Company Entering EU","prompt":"You are a data protection attorney advising a US-based B2B SaaS company with 50 enterprise customers in Germany, France, and the Netherlands that has been operating without a formal GDPR compliance program. The company processes HR data on behalf of its customers. Conduct a GDPR compliance gap analysis covering: whether the company qualifies as a data processor, controller, or both and why this determines its compliance obligations, the legal basis mapping required under Article 6 for each category of personal data processed, the EU representative appointment requirement under Article 27 for non-EU companies, the records of processing activities (RoPA) requirement under Article 30 and how to build it from scratch, the data subject rights response procedures required (access, erasure, portability) and the 30-day response clock, the DPIA trigger assessment for high-risk processing activities, and the Data Protection Officer appointment requirement under Article 37. Prioritize the gaps by enforcement risk. For educational purposes — consult a qualified attorney for legal advice.","tags":["privacy","gdpr","compliance","saas"],"author":"AINOW","created":"2024-02-15T13:00:00Z","featured":true},

  {"id":"leg-38","title":"CCPA and CPRA Compliance Program for E-Commerce","prompt":"You are a California privacy attorney advising a mid-size e-commerce company with $35M in annual revenue and a customer database of 1.2 million California consumers. The company has not updated its privacy program since the CCPA's initial effective date and now faces CPRA enforcement by the new California Privacy Protection Agency. Conduct a CPRA compliance review covering: the expanded sensitive personal information category and the opt-out-of-use right that goes beyond the CCPA's opt-out-of-sale right, the new data minimization and purpose limitation obligations under CPRA, the contractor versus service provider versus third party distinction and why misclassification creates direct liability, the updated privacy notice requirements including the 'Do Not Share My Personal Information' link for cross-context behavioral advertising, the opt-out preference signal (Global Privacy Control) technical compliance requirement, employee and B2B data coverage under CPRA, and the enforcement risk scoring given the company's revenue and data volumes. For educational purposes — consult a qualified attorney for legal advice.","tags":["privacy","ccpa","cpra","california"],"author":"AINOW","created":"2024-02-15T13:05:00Z","featured":false},

  {"id":"leg-39","title":"HIPAA Security Rule Risk Analysis for Cloud Migration","prompt":"You are a healthcare privacy attorney advising a regional hospital network that is migrating its electronic health record system from on-premises infrastructure to a cloud environment hosted by a major cloud provider. Conduct a HIPAA Security Rule risk analysis covering: the required risk analysis methodology under 45 CFR 164.308(a)(1) and why it must be updated before the migration, the Business Associate Agreement requirements with the cloud provider and the specific provisions that major cloud vendors (AWS, Azure, GCP) typically include or exclude, the encryption standard adequacy for ePHI in transit and at rest and why NIST SP 800-111 is the relevant guidance, access control requirements including the automatic logoff and unique user identification standards, the audit control and activity logging requirements and how long logs must be retained, and the contingency plan and disaster recovery requirements that must be tested after migration. Flag the top five HIPAA enforcement priorities under recent OCR audit findings. For educational purposes — consult a qualified attorney for legal advice.","tags":["privacy","hipaa","healthcare","cloud"],"author":"AINOW","created":"2024-02-15T13:10:00Z","featured":false},

  {"id":"leg-40","title":"Biometric Data Privacy Compliance for Illinois BIPA","prompt":"You are a privacy attorney advising a manufacturing company with facilities in Illinois that has deployed a fingerprint-based time and attendance system for its 400 hourly workers. The company has just been named in a class action lawsuit under the Illinois Biometric Information Privacy Act (BIPA). Analyze the litigation exposure covering: the elements of a BIPA claim and whether consent obtained at onboarding was legally adequate under the specific written disclosure and written release requirements, the statutory damages structure ($1,000 per negligent violation, $5,000 per intentional violation) and how per-scan versus per-person damages calculations have played out in Illinois courts, the strict liability nature of BIPA and why the lack of actual harm is not a defense, the class certification risk and why BIPA class actions routinely result in massive settlements, the statute of limitations analysis following the Illinois Supreme Court's ruling in Tims v. Black Horse Carriers, and the remediation steps the company should implement immediately including a retrospective consent campaign and a retention/destruction schedule. For educational purposes — consult a qualified attorney for legal advice.","tags":["privacy","bipa","illinois","biometric"],"author":"AINOW","created":"2024-02-15T13:15:00Z","featured":false},

  {"id":"leg-41","title":"Data Breach Response Legal Protocol","prompt":"You are a privacy and cybersecurity attorney advising a healthcare technology company that has just discovered a ransomware attack that encrypted its servers and exfiltrated approximately 85,000 patient records containing PHI. The attack was discovered at 11 PM on a Friday. Draft a 72-hour data breach response legal protocol covering: the immediate steps in the first hour including forensic evidence preservation and incident response retainer activation, the HIPAA Breach Notification Rule and the 60-day notification clock to HHS and affected individuals, the state breach notification law analysis for the 12 states where affected patients reside including California's 45-day notification requirement, the SEC Form 8-K disclosure obligation if the company has publicly traded securities under the SEC's 2023 cybersecurity disclosure rules, attorney-client privilege protection for the forensic investigation report, and the HHS Office for Civil Rights investigation protocol and how to respond to an OCR data request. For educational purposes — consult a qualified attorney for legal advice.","tags":["privacy","data-breach","hipaa","cybersecurity"],"author":"AINOW","created":"2024-02-15T13:20:00Z","featured":false},

  {"id":"leg-42","title":"Children's Online Privacy COPPA Compliance Audit","prompt":"You are a privacy attorney conducting a COPPA compliance audit for an ed-tech company that operates a learning platform used by students in K-12 schools. The platform collects student names, email addresses, learning performance data, and device identifiers. Analyze the COPPA compliance requirements covering: the 'actual knowledge' standard for knowing a user is under 13 and the school operator exception that allows schools to consent on behalf of parents, the FTC's 2024 COPPA Rule update and the new requirements for EdTech companies including data retention and deletion obligations, the prohibition on using student data for behavioral advertising and how this interacts with the platform's use of analytics providers, the Student Online Personal Information Protection Act (SOPIPA) in California and analogous state laws, the privacy notice requirements and what must appear on the homepage versus the collection point, and the data deletion obligation when a child's account is closed. [Describe the legal situation or dispute] For educational purposes — consult a qualified attorney for legal advice.","tags":["privacy","coppa","edtech","children"],"author":"AINOW","created":"2024-02-15T13:25:00Z","featured":false},

  {"id":"leg-43","title":"Demand Letter for Breach of Software Development Contract","prompt":"You are a commercial litigation attorney drafting a pre-litigation demand letter on behalf of a technology startup against a software development agency that delivered a mobile application nine months late and with critical defects that caused the startup to miss its launch window and lose a signed $2M enterprise customer. The contract had a liquidated damages clause of $10,000 per week of delay and a warranty for 12 months post-delivery. Draft the demand letter covering: a precise recitation of the contract terms breached including the milestone schedule, the delivery obligation, and the warranty terms, quantification of all damages including liquidated damages, direct damages from the lost customer, and consequential damages for investor confidence harm, the legal basis for breach of contract and breach of implied warranty of merchantability, the specific cure demand and the deadline for response before litigation commences, and a litigation preview that credibly signals the startup's willingness to file. For educational purposes — consult a qualified attorney for legal advice.","tags":["litigation","contracts","demand-letter","technology"],"author":"AINOW","created":"2024-02-15T13:30:00Z","featured":false},

  {"id":"leg-44","title":"Securities Fraud Class Action Defense Strategy","prompt":"You are a securities defense attorney advising the board of directors of a publicly traded company that has just received a securities class action complaint alleging violations of Section 10(b) of the Exchange Act and SEC Rule 10b-5 following a 40% stock price drop after the company disclosed that its flagship product had failed a key clinical trial. The complaint alleges that the company made materially false statements about clinical trial progress in its quarterly earnings calls. Analyze the defense strategy covering: the PSLRA's heightened pleading standards and why the 'strong inference' of scienter requirement is a powerful early dismissal tool, the falsity analysis and the distinction between knowingly false statements and optimistic forward-looking statements protected by the PSLRA safe harbor, the materiality standard under Basic Inc. v. Levinson and the fraud-on-the-market presumption, the motion to dismiss strategy and the statistical probability of dismissal in the relevant circuit, the D&O insurance coverage analysis and the interplay between the SCA and the duty to defend, and the litigation timeline and settlement dynamics in securities class actions. For educational purposes — consult a qualified attorney for legal advice.","tags":["litigation","securities","class-action","corporate"],"author":"AINOW","created":"2024-02-15T13:35:00Z","featured":false},

  {"id":"leg-45","title":"Commercial Arbitration Strategy and Clause Drafting","prompt":"You are a dispute resolution attorney advising a technology company that has been served with a demand for AAA arbitration by a former distribution partner claiming $8M in lost profits from an alleged wrongful termination of their distribution agreement. Analyze the arbitration strategy and recommend improvements to future arbitration clauses covering: the initial jurisdictional and procedural challenges available including delegation clause analysis and whether the arbitrability question goes to the arbitrator or the court, the AAA Commercial Arbitration Rules discovery provisions and the strategy for limiting e-discovery costs in a large commercial dispute, the arbitrator selection process and the criteria for challenging an arbitrator for evident partiality, the consolidation of related claims and multi-party arbitration issues, confidentiality of arbitration proceedings and the limits of that confidentiality in securities and public interest contexts, and the grounds for vacating an arbitration award under the Federal Arbitration Act Section 10 and why they are extremely narrow. For educational purposes — consult a qualified attorney for legal advice.","tags":["litigation","arbitration","aaa","dispute-resolution"],"author":"AINOW","created":"2024-02-15T13:40:00Z","featured":false},

  {"id":"leg-46","title":"Employment Discrimination Charge Response Strategy","prompt":"You are an employment litigation attorney advising an employer that has received an EEOC Charge of Discrimination from a former employee alleging race discrimination and retaliation under Title VII. The employee was terminated after an investigation into a workplace altercation in which the employee claims white comparators received less severe discipline. Draft the EEOC position statement strategy covering: the document preservation and litigation hold obligations triggered by receipt of the charge, the McDonnell Douglas burden-shifting framework and what your position statement must establish to defeat the discrimination claim at the EEOC stage, the comparator evidence analysis and how to address the argument that white employees in similar situations received lesser discipline, the anti-retaliation legal standard and the temporal proximity problem if the termination was close in time to any protected activity, the confidentiality restrictions on EEOC position statements following the Commission's 2016 guidance change, and the right-to-sue letter timing strategy and mediation program considerations. [Describe the legal situation or dispute] For educational purposes — consult a qualified attorney for legal advice.","tags":["employment","eeoc","litigation","discrimination"],"author":"AINOW","created":"2024-02-15T13:45:00Z","featured":false},

  {"id":"leg-47","title":"Preliminary Injunction Motion for Trade Secret Misappropriation","prompt":"You are a trade secret litigator drafting a motion for preliminary injunction under the Defend Trade Secrets Act (DTSA) in the Northern District of California against a former CTO who left to found a competing company and is using the plaintiff's proprietary machine learning architecture. Draft the motion structure covering: the four-factor Winter test for preliminary injunctions (likelihood of success on the merits, irreparable harm, balance of equities, public interest) and how each factor applies to trade secret cases, the 'reasonable measures' evidence needed to demonstrate the information qualifies as a trade secret, the digital forensics declaration establishing the evidence of actual misappropriation, the irreparable harm argument and why money damages are inadequate for trade secret misappropriation, the specific injunctive relief terms to request including a bring-back-order for specific devices and an audit of the competing company's codebase, and the bond requirement under FRCP 65(c) and how to argue for a minimal bond. For educational purposes — consult a qualified attorney for legal advice.","tags":["litigation","trade-secrets","injunction","dtsa"],"author":"AINOW","created":"2024-02-15T13:50:00Z","featured":false},

  {"id":"leg-48","title":"Cross-Border Mediation Strategy for Commercial Dispute","prompt":"You are a dispute resolution attorney advising a US technology company in a $15M commercial dispute with a German automotive parts manufacturer over an alleged breach of a multi-year supply agreement. The contract has a mediation-first clause before arbitration under ICC Rules. Develop a cross-border mediation strategy covering: the mediator selection criteria for a US-German commercial dispute and whether to seek a mediator from the International Mediation Institute or CPR, the information exchange protocol in mediation and how to share financial damages information without creating discovery obligations in subsequent arbitration, the authority-to-settle requirements and who must appear at the mediation with real settlement authority, the cultural dimensions of US versus German negotiation styles and how they affect mediation strategy, the confidentiality protections for mediation communications under the Uniform Mediation Act and German law, and the term sheet drafting strategy to quickly document any settlement reached before parties return home. For educational purposes — consult a qualified attorney for legal advice.","tags":["litigation","mediation","international","commercial"],"author":"AINOW","created":"2024-02-15T13:55:00Z","featured":false},

  {"id":"leg-49","title":"Class Action Waiver and Arbitration Agreement Defense","prompt":"You are an employment defense attorney advising a national retail company that requires all hourly employees to sign a mandatory arbitration agreement with class action waiver as a condition of employment. The company has just been served with a PAGA representative action in California alleging wage and hour violations on behalf of 3,000 employees. Analyze: the Epic Systems v. Lewis holding affirming class action waivers in employment arbitration agreements under the FAA, the California Supreme Court's Viking River Cruises v. Moriana decision on PAGA claim arbitrability and the current state of the law after Adolph v. Uber Technologies, the specific PAGA waiver drafting requirements following the Viking River decision and whether your current agreement is adequate, the strategic decision whether to compel arbitration of individual PAGA claims while the representative PAGA claim proceeds in court, the representative PAGA litigation exposure calculation and settlement negotiation dynamics, and the legislative reform risk given California's ongoing attempts to modify PAGA. [Paste the contract clause or document excerpt] For educational purposes — consult a qualified attorney for legal advice.","tags":["employment","arbitration","paga","class-action"],"author":"AINOW","created":"2024-02-15T14:00:00Z","featured":false},

  {"id":"leg-50","title":"Litigation Hold Notice and ESI Preservation Protocol","prompt":"You are a litigation attorney drafting a litigation hold and electronically stored information (ESI) preservation protocol for a financial services company that has just been named as a defendant in a putative class action alleging deceptive practices in its mortgage servicing operations. The company processes 50,000 loans and uses seven different software systems to manage customer communications. Draft the litigation hold and preservation protocol covering: the scope of the hold including all relevant custodians, data sources (email, Slack, Salesforce, loan origination system), and time periods, the specific preservation steps required for each data source including auto-delete and auto-archive suspension, the data collection methodology and the chain-of-custody requirements for forensically sound collection, the obligations of IT personnel and why failure to suspend auto-delete can constitute spoliation, the proportionality analysis under FRCP 26(b)(1) and how to document cost-shifting arguments for burdensome preservation, and the ongoing hold management including updates as new custodians and claims are identified. For educational purposes — consult a qualified attorney for legal advice.","tags":["litigation","esi","discovery","financial-services"],"author":"AINOW","created":"2024-02-15T14:05:00Z","featured":false},

  {"id":"leg-51","title":"Commercial Office Lease Negotiation for Growing Startup","prompt":"You are a real estate attorney advising a Series B startup negotiating a 10,000 square foot office lease in a Class A building in San Francisco for a 7-year term. The landlord has presented a standard form lease that heavily favors the landlord. Negotiate the following critical tenant protections covering: the operating expense 'gross-up' provision and why you need a base year stop and a cap on controllable expense increases, the assignment and subletting rights the company needs to accommodate a future M&A transaction or downsizing, the co-tenancy clause tied to the anchor tenant occupancy and what happens to rent if the anchor leaves, the personal guarantee demand and how to negotiate it down to a 6-month letter of credit burn-down, the build-out allowance structure and ownership of improvements including the restoration obligation, and the force majeure and rent abatement provisions covering pandemic-level events that make the space unusable. Provide specific alternative language for each negotiated term. For educational purposes — consult a qualified attorney for legal advice.","tags":["real-estate","commercial-lease","startup","negotiation"],"author":"AINOW","created":"2024-02-15T14:10:00Z","featured":false},

  {"id":"leg-52","title":"Residential Purchase Agreement Due Diligence Review","prompt":"You are a real estate attorney advising a buyer purchasing a $1.8M single-family home in Marin County, California. The property is on a hillside lot with a creek running through the rear portion. Review the standard California Residential Purchase Agreement (CAR Form RPA) and advise on: the contingency management strategy for the inspection, appraisal, and loan contingency periods including the active removal requirement versus passive removal and the risks of each, the specific environmental due diligence needed for a hillside lot including geological hazard zone disclosures, creek setback requirements under local ordinance, and potential FEMA flood zone designations, the Natural Hazard Disclosure requirements under California Civil Code 1102 including fire hazard severity zones under the new CAL FIRE designations post-Camp Fire, the mechanics of the seller's disclosure obligations and what triggers rescission rights for undisclosed material defects, the title insurance coverage analysis including the distinction between standard and ALTA extended coverage for a survey exception, and the HOA document review requirements if applicable. For educational purposes — consult a qualified attorney for legal advice.","tags":["real-estate","residential","california","purchase"],"author":"AINOW","created":"2024-02-15T14:15:00Z","featured":false},

  {"id":"leg-53","title":"Commercial Real Estate Purchase and Leaseback Transaction","prompt":"You are a real estate attorney structuring a sale-leaseback transaction for a manufacturing company that owns its 120,000 square foot production facility in suburban Chicago and wants to monetize the real estate while retaining operational control through a long-term triple-net lease. Structure the transaction covering: the valuation methodology for industrial real estate and the cap rate analysis used by sale-leaseback buyers, the triple-net lease structure and the distinction between NNN and absolute net leases and which is more appropriate for a credit tenant, the lease term and renewal option structure that gives the seller-tenant operational certainty while giving the buyer-landlord an attractive investment, the purchase price adjustment mechanics based on the final agreed lease rate and cap rate, the right of first offer or right of first refusal for the seller-tenant to repurchase the property, the tax treatment of the gain on sale and the Section 1031 exchange considerations from the buyer's perspective, and the lender consent requirements if the property has existing debt that must be satisfied at closing. For educational purposes — consult a qualified attorney for legal advice.","tags":["real-estate","commercial","leaseback","tax"],"author":"AINOW","created":"2024-02-15T14:20:00Z","featured":false},

  {"id":"leg-54","title":"Land Use and Zoning Variance Application","prompt":"You are a land use attorney representing a developer seeking to convert a 40,000 square foot former department store in a Massachusetts town center into a mixed-use development with ground-floor retail and 45 market-rate residential units above. The property is zoned for commercial use only and requires a special permit and zoning relief for residential use. Advise on the land use approval process covering: the Massachusetts Chapter 40A variance and special permit standards and why variances are intentionally difficult to obtain while special permits offer a more practical path, the public hearing strategy and how to present traffic, parking, and design elements to the planning board to minimize neighbor opposition, the Chapter 40B comprehensive permit alternative if 25% of the units are affordable housing and how it supersedes local zoning, the environmental and historic preservation review triggers given the building's age and location, the developer agreement or host community agreement that the town will likely require, and the litigation risk from neighbor appeal under Chapter 40A Section 17 and how to structure the approval to minimize appeal vulnerability. For educational purposes — consult a qualified attorney for legal advice.","tags":["real-estate","zoning","land-use","massachusetts"],"author":"AINOW","created":"2024-02-15T14:25:00Z","featured":false},

  {"id":"leg-55","title":"Construction Contract Dispute and Mechanic's Lien","prompt":"You are a construction law attorney advising a general contractor who has completed $800,000 of work on a commercial renovation project in Texas and has not been paid the final $220,000 because the property owner claims defective workmanship. The property owner has also withheld a retainage of 10%. Analyze the legal remedies covering: the Texas mechanic's lien statute requirements including the constitutional lien, statutory lien, and the critical monthly notice deadlines that must have been met to preserve lien rights, the lien filing deadlines and the consequences of missing them, the fund-trapping notice to the property owner and lender and why it is a critical protective step under Texas Property Code Chapter 162, the bond-over and release of lien procedures once litigation commences, the construction defect claim analysis and the contractor's right to cure under the Texas Residential Construction Liability Act (if applicable), and the payment bond claim if the project is bonded. [Describe the legal situation or dispute] For educational purposes — consult a qualified attorney for legal advice.","tags":["real-estate","construction","lien","texas"],"author":"AINOW","created":"2024-02-15T14:30:00Z","featured":false},

  {"id":"leg-56","title":"Commercial Lease Default and Eviction Proceedings","prompt":"You are a commercial real estate attorney advising a landlord whose anchor restaurant tenant in a mixed-use development has stopped paying rent for four months, owing $280,000 in unpaid rent and CAM charges. The tenant has sent a letter claiming constructive eviction due to HVAC failures. Analyze the landlord's legal position and eviction strategy covering: the Texas or California (choose the most relevant) unlawful detainer procedure for commercial tenants and the required notice periods and cure rights under the lease, the constructive eviction defense elements the tenant must prove and why the landlord's maintenance history is critical evidence, the commercial lockout statutes and why self-help eviction without court process creates serious landlord liability even in states that technically permit it, the mitigation obligation and whether the landlord must actively market the space, the personal guarantee enforcement strategy if a principal of the tenant entity personally guaranteed the lease, and the security deposit forfeiture and holdover rent provisions. [Paste the contract clause or document excerpt] For educational purposes — consult a qualified attorney for legal advice.","tags":["real-estate","commercial-lease","eviction","landlord"],"author":"AINOW","created":"2024-02-15T14:35:00Z","featured":false},

  {"id":"leg-57","title":"1031 Exchange Structuring for Commercial Real Estate","prompt":"You are a real estate and tax attorney advising a real estate investor who has a $3.2M gain on the sale of a commercial apartment complex in Phoenix, Arizona and wants to complete a Section 1031 like-kind exchange into two replacement properties — a retail strip center in Texas and an industrial building in Nevada. Structure the 1031 exchange covering: the strict 45-day identification period and the three-property rule versus the 200% rule and which strategy applies given the investor's situation, the 180-day closing deadline and how holidays and weekends can create traps, the qualified intermediary requirements and why using the investor's own attorney or accountant as QI invalidates the exchange, the boot calculation and how taking out mortgage relief or receiving cash creates a taxable gain, the related-party restriction and why buying from a family member or controlled entity triggers recapture, the Delaware Statutory Trust (DST) as a backup replacement property strategy if the primary properties fall through, and the depreciation recapture obligation under Section 1250 even if the exchange is otherwise tax-free. For educational purposes — consult a qualified attorney for legal advice.","tags":["real-estate","tax","1031-exchange","investment"],"author":"AINOW","created":"2024-02-15T14:40:00Z","featured":false},

  {"id":"leg-58","title":"Short-Term Rental Regulatory Compliance Analysis","prompt":"You are a real estate attorney advising an investor who owns 12 residential units in New Orleans, Louisiana that have been operated as short-term rentals on Airbnb and Vrbo. New Orleans has enacted a new ordinance significantly restricting non-owner-occupied short-term rentals, and the investor's existing platform licenses are now subject to revocation. Analyze the regulatory compliance situation covering: the New Orleans short-term rental ordinance requirements for non-owner-occupied platforms including the commercial short-term rental permit requirements, the vested rights and regulatory takings analysis and whether pre-existing permits create a legally protected right to continue operations during a phase-out period, the Louisiana constitutional takings doctrine and the viability of a compensation claim if the regulations destroy a substantial portion of property value, the appeal process through the City Planning Commission and Board of Zoning Adjustments, the federal preemption argument regarding the Fair Housing Act and whether restrictions that effectively target certain neighborhoods raise discriminatory impact concerns, and the best compliance strategy for converting units to long-term rentals. For educational purposes — consult a qualified attorney for legal advice.","tags":["real-estate","short-term-rental","regulatory","zoning"],"author":"AINOW","created":"2024-02-15T14:45:00Z","featured":false},

  {"id":"leg-59","title":"Environmental Due Diligence for Industrial Property Acquisition","prompt":"You are an environmental attorney advising a private equity fund acquiring a portfolio of five former industrial properties in the Rust Belt for conversion to logistics centers. Several properties have known soil and groundwater contamination from prior dry-cleaning operations and light manufacturing. Structure the environmental due diligence and liability protection strategy covering: the Phase I and Phase II Environmental Site Assessment standards under ASTM E1527-21 and E1903-19 and why the Phase II scope must be carefully negotiated with the environmental consultant, the CERCLA innocent landowner, bona fide prospective purchaser, and contiguous property owner defenses and the specific AAI (All Appropriate Inquiries) steps required to qualify, the state voluntary cleanup program options in Ohio, Pennsylvania, and Michigan and the liability protections each offers including covenant not to sue, the environmental indemnification provisions needed in the purchase agreement and the limitations on seller indemnification given the seller is a corporate entity that will be dissolved, the environmental representations and warranties and the environmental escrow structure, and the brownfield tax incentives available for redevelopment. For educational purposes — consult a qualified attorney for legal advice.","tags":["real-estate","environmental","cercla","acquisition"],"author":"AINOW","created":"2024-02-15T14:50:00Z","featured":false},

  {"id":"leg-60","title":"Opportunity Zone Investment Fund Legal Structure","prompt":"You are a tax and real estate attorney advising a group of investors forming a Qualified Opportunity Zone Fund (QOF) to invest $20M in a mixed-use development project in a designated Opportunity Zone in Detroit, Michigan. Structure the QOF covering: the entity structure requirements for a QOF (partnership or corporation) and why a partnership provides greater tax flexibility, the 90% asset test and the semi-annual testing dates that require the fund manager's careful attention, the 31-month substantial improvement requirement and the documentation needed to prove the original use or substantial improvement standard, the working capital safe harbor and how to document the 62-month written schedule, the investor-level versus fund-level elections and the implications for investors who hold for 10 years to receive the full gain exclusion, the qualified opportunity zone business property requirements and the specific 70% tangible property test, and the exit strategy tax modeling for investors at the 5-year, 7-year, and 10-year holding periods. For educational purposes — consult a qualified attorney for legal advice.","tags":["real-estate","tax","opportunity-zone","investment"],"author":"AINOW","created":"2024-02-15T14:55:00Z","featured":false},

  {"id":"leg-61","title":"FDA Medical Device 510(k) Clearance Regulatory Strategy","prompt":"You are a regulatory attorney advising a medical device startup that has developed a software-based clinical decision support tool that analyzes radiology images using AI to flag potential pulmonary embolisms. The company needs to determine its regulatory pathway with the FDA. Analyze the regulatory strategy covering: the FDA's Software as a Medical Device (SaMD) framework and the International Medical Device Regulators Forum (IMDRF) risk classification for the company's specific intended use, whether the device qualifies as a Non-Device Clinical Decision Support (CDS) tool under the 21st Century Cures Act or requires 510(k) clearance as a Class II device, the predicate device search strategy for a 510(k) substantial equivalence argument and the risks of using an AI-based predicate versus a legacy device predicate, the De Novo classification pathway as an alternative if no suitable predicate exists, the predetermined change control plan (PCCP) requirements for AI/ML-based devices under FDA's 2024 guidance, and the clinical validation study design needed to support a 510(k) submission. For educational purposes — consult a qualified attorney for legal advice.","tags":["regulatory","fda","medical-device","ai"],"author":"AINOW","created":"2024-02-15T15:00:00Z","featured":false},

  {"id":"leg-62","title":"FinTech Money Transmission Licensing Strategy","prompt":"You are a financial regulatory attorney advising a fintech company that has built a peer-to-peer payment platform and needs to analyze its licensing obligations before a national launch. The platform allows users to send money to each other and to small businesses. Analyze the regulatory licensing requirements covering: the state money transmission licensing patchwork and why 49 states (all except Montana) require a money transmitter license with varying capital, bonding, and net worth requirements, the NMLS Multi-State Licensing Process and the fastest pathway to achieving coverage in all required states, the federal Bank Secrecy Act (BSA) registration as a Money Services Business (MSB) with FinCEN and the AML/KYC program requirements, the IRS Form 1099-K reporting obligations triggered by transaction volume, the OCC Fintech Charter and state banking department alternatives for a national license, and the partnership bank model as an alternative to direct licensing and its compliance obligations under the Durbin Amendment and Reg E. For educational purposes — consult a qualified attorney for legal advice.","tags":["regulatory","fintech","money-transmission","licensing"],"author":"AINOW","created":"2024-02-15T15:05:00Z","featured":false},

  {"id":"leg-63","title":"Cannabis Business Regulatory Compliance in Multi-State Operations","prompt":"You are a cannabis regulatory attorney advising a cannabis company that holds retail and cultivation licenses in Colorado and California and is evaluating expansion into New Jersey and New York. Conduct a regulatory compliance analysis covering: the state-specific ownership and financial disclosure requirements that vary significantly between the four states and create challenges for institutional investors, the federal Schedule I Controlled Substance Act conflict and why the 280E tax code provision disallowing deductions for cannabis businesses is the most significant federal compliance burden, the FinCEN guidance on banking for cannabis businesses and the current state of cannabis banking including the SAFER Banking Act's legislative status, the track-and-trace systems (Metrc in most states) and the compliance obligations for seed-to-sale tracking, the interstate commerce prohibition and why conducting any multi-state business activities creates federal enforcement risk, and the social equity and license transfer restrictions in New York that affect M&A transactions in that market. For educational purposes — consult a qualified attorney for legal advice.","tags":["regulatory","cannabis","multi-state","compliance"],"author":"AINOW","created":"2024-02-15T15:10:00Z","featured":false},

  {"id":"leg-64","title":"Government Contracts FAR/DFARS Compliance for Small Business","prompt":"You are a government contracts attorney advising a cybersecurity software company that has won its first Department of Defense contract worth $4.5M. The contract is subject to FAR and DFARS regulations and contains a DFARS 252.204-7012 clause requiring Cybersecurity Maturity Model Certification (CMMC) compliance. Analyze the compliance obligations covering: the DFARS 252.204-7012 safeguarding requirements for Controlled Unclassified Information (CUI) and the 72-hour cyber incident reporting obligation to DC3 and the Contracting Officer, the CMMC 2.0 Level 2 requirements and whether the company must use a C3PAO for a third-party assessment or can self-attest, the flow-down requirements to subcontractors and suppliers who handle CUI, the False Claims Act exposure for misrepresenting cybersecurity compliance status following the DOJ's Cyber Fraud Initiative, the System for Award Management (SAM.gov) registration maintenance and the small business certification accuracy obligations, and the limitation on subcontracting requirements for small business set-aside awards. For educational purposes — consult a qualified attorney for legal advice.","tags":["regulatory","government-contracts","dfars","cybersecurity"],"author":"AINOW","created":"2024-02-15T15:15:00Z","featured":false},

  {"id":"leg-65","title":"Telehealth Platform Regulatory Compliance Analysis","prompt":"You are a healthcare regulatory attorney advising a telehealth platform company that connects patients with licensed physicians for prescription of Schedule IV controlled substances and offers mental health counseling services across 35 states. Analyze the regulatory compliance obligations covering: the DEA's telemedicine prescribing rules for controlled substances and the post-COVID unwinding of the Ryan Haight Act flexibilities including the DEA's new special telemedicine registration requirements, the state medical practice act requirements including whether the company's platform model triggers the corporate practice of medicine doctrine and what structures (MSO model, fee-for-service) avoid it, the HIPAA compliance requirements specific to telehealth including the business associate relationships with video platform vendors, the state telehealth parity laws requiring insurance coverage of telehealth at in-person rates and which states have enacted them, the FTC Act Section 5 enforcement risk for health-related advertising claims, and the state prescription drug monitoring program (PDMP) access obligations for providers prescribing controlled substances via telemedicine. For educational purposes — consult a qualified attorney for legal advice.","tags":["regulatory","telehealth","healthcare","dea"],"author":"AINOW","created":"2024-02-15T15:20:00Z","featured":false},

  {"id":"leg-66","title":"Cryptocurrency Exchange Registration and Compliance","prompt":"You are a financial regulatory attorney advising the founders of a cryptocurrency exchange platform that facilitates spot trading of digital assets and is evaluating its regulatory status and compliance obligations. Analyze the regulatory landscape covering: the SEC's position that most tokens other than Bitcoin and Ether are securities under the Howey test and the enforcement risk of listing unregistered securities, the CFTC's jurisdiction over crypto derivatives and spot commodity markets and why operating a derivatives exchange without CFTC registration creates criminal exposure, the FinCEN money services business registration requirements and the AML/KYC program obligations under the Bank Secrecy Act, the state licensing requirements including New York's BitLicense and whether the company needs separate licenses in each state, the OFAC sanctions compliance program requirements for blocking transactions to sanctioned jurisdictions and individuals, and the strategic decision between registering as a national securities exchange, an ATS (Alternative Trading System), or exiting the US market. For educational purposes — consult a qualified attorney for legal advice.","tags":["regulatory","crypto","sec","fintech"],"author":"AINOW","created":"2024-02-15T15:25:00Z","featured":false},

  {"id":"leg-67","title":"Environmental Permitting for Manufacturing Expansion","prompt":"You are an environmental regulatory attorney advising a specialty chemical manufacturer planning to expand its production facility in Texas by adding two new production lines that will increase its air emissions and wastewater discharge. Analyze the environmental permitting requirements covering: the Clean Air Act New Source Review (NSR) Prevention of Significant Deterioration (PSD) permit requirements and the emissions threshold analysis to determine if the expansion triggers major source permitting, the Texas Commission on Environmental Quality (TCEQ) permit-by-rule versus standard permit pathway and the public comment period risks, the Clean Water Act NPDES permit modifications needed for the increased wastewater discharge and the Texas Pollutant Discharge Elimination System (TPDES) permit amendment process, the RCRA hazardous waste generator status changes and the large quantity generator compliance requirements triggered by the expansion, the community right-to-know Tier II chemical inventory reporting changes under EPCRA, and the environmental justice analysis for a facility in a historically underserved community and its impact on permit approval likelihood. For educational purposes — consult a qualified attorney for legal advice.","tags":["regulatory","environmental","manufacturing","texas"],"author":"AINOW","created":"2024-02-15T15:30:00Z","featured":false},

  {"id":"leg-68","title":"SEC Regulation Crowdfunding Compliance for Startup","prompt":"You are a securities attorney advising a clean energy startup that wants to raise up to $5M from retail investors using Regulation Crowdfunding (Reg CF) through a registered FINRA funding portal. Walk through the Reg CF compliance requirements covering: the $5M annual cap and the interaction with concurrent Regulation D and Regulation A offerings under the integration doctrine, the investor investment limits based on net worth and annual income and the funding portal's obligation to verify compliance, the Form C disclosure requirements including the two-year financial statement and the audit requirement for raises over $1.235M, the ongoing reporting obligations under Form C-AR and the triggers for Form C-U updates, the advertising restrictions and the 'tombstone' communication rules during the offering period, the escrow and cancellation mechanics and what happens if the target amount is not reached, and the resale restrictions on Reg CF securities and the 12-month holding period. Flag the three most common Reg CF disclosure deficiencies that lead to SEC comment letters. For educational purposes — consult a qualified attorney for legal advice.","tags":["regulatory","securities","crowdfunding","startup"],"author":"AINOW","created":"2024-02-15T15:35:00Z","featured":false},

  {"id":"leg-69","title":"FTC Advertising Compliance and Endorsement Disclosure","prompt":"You are a regulatory and advertising attorney advising a direct-to-consumer supplement company that uses influencer marketing, celebrity endorsements, and user testimonials across Instagram, TikTok, YouTube, and its own website. Conduct an FTC compliance review covering: the FTC's 2023 updated Endorsement Guides and the specific disclosure requirements for paid social media posts including the placement, format, and wording of disclosures (why 'ad' in hashtags is generally adequate but 'sp' or 'partner' are insufficient), the substantiation standard for health and efficacy claims including the 'competent and reliable scientific evidence' standard and what clinical studies actually satisfy it, the prohibition on fake reviews and the FTC's 2024 final rule on fake reviews including civil penalties, the negative option rule and its application to subscription billing for the company's autoship program, the FTC's health products compliance program requirements, and the state consumer protection law overlay including California's automatic renewal law requirements. [Describe the legal situation or dispute] For educational purposes — consult a qualified attorney for legal advice.","tags":["regulatory","ftc","advertising","compliance"],"author":"AINOW","created":"2024-02-15T15:40:00Z","featured":false},

  {"id":"leg-70","title":"ERISA Fiduciary Compliance for 401(k) Plan Sponsor","prompt":"You are an ERISA attorney advising the HR director of a 500-person technology company that sponsors a 401(k) plan with $45M in assets. The company has just received a demand letter from a plaintiffs' firm alleging that the plan's investment options have excessive fees and that the company breached its fiduciary duty by failing to monitor the recordkeeper and investment lineup. Analyze the ERISA fiduciary exposure covering: the prudent man standard of care under ERISA Section 404(a) and the procedural prudence doctrine that protects fiduciaries who follow a documented process, the regular benchmarking obligation for recordkeeping fees and investment expense ratios and what constitutes an adequate monitoring process, the prohibited transaction rules and the exceptions available for service provider compensation arrangements, the mandatory 401(k) fee disclosure requirements under ERISA Section 408(b)(2) and whether the recordkeeper has provided compliant disclosures, the statute of limitations under ERISA Section 413 and the three-year versus six-year limitations period for breach of fiduciary duty claims, and the plan committee governance structure and the use of an ERISA Section 3(21) investment adviser versus a 3(38) discretionary manager to shift liability. For educational purposes — consult a qualified attorney for legal advice.","tags":["regulatory","erisa","retirement","fiduciary"],"author":"AINOW","created":"2024-02-15T15:45:00Z","featured":false},

  {"id":"leg-71","title":"Cross-Border SaaS Agreement for EU Customer","prompt":"You are a technology transactions attorney drafting a SaaS agreement between a US-based software company and a large German manufacturing corporation. The agreement must be compliant with GDPR, German contract law requirements, and the EU AI Act where applicable. Draft the key cross-border provisions covering: the governing law and jurisdiction clause and the tension between US arbitration preference and German courts' reluctance to enforce US arbitration clauses for consumer and quasi-consumer transactions, the GDPR Article 28 Data Processing Agreement that must be incorporated as an exhibit including the EU Standard Contractual Clauses (Module 2) for the US data transfer, the warranty standards under German law (BGB) which imply stronger warranties than US commercial law, the force majeure clause and how German impossibility doctrine (§275 BGB) differs from common law force majeure, the automatic renewal and cancellation notice requirements under German distance selling law, and the EU AI Act compliance obligations if the software constitutes a high-risk AI system under Annex III. For educational purposes — consult a qualified attorney for legal advice.","tags":["international","saas","gdpr","germany"],"author":"AINOW","created":"2024-02-15T15:50:00Z","featured":false},

  {"id":"leg-72","title":"International Distribution Agreement for Asia-Pacific Expansion","prompt":"You are an international commercial attorney advising a US medical device company entering the Asia-Pacific market through a network of exclusive distributors in Japan, South Korea, Singapore, and Australia. Draft the international distribution agreement framework covering: the exclusive territory grant and the competition law compliance requirements including Japanese Anti-Monopoly Act restrictions on resale price maintenance, the Foreign Corrupt Practices Act (FCPA) compliance provisions including the distributor due diligence requirements and the FCPA compliance representations and warranties that must be included, the minimum purchase commitment structure and the consequences of failure to meet quotas without forfeiting exclusivity, the product registration and regulatory approval obligations in each jurisdiction and who bears the cost and owns the registration data, the termination provisions and the local franchise law or distributor protection law that restricts termination in certain jurisdictions (Japan's commercial agency laws, South Korea's Distribution Act), and the governing law and dispute resolution provisions including whether Singapore International Arbitration Centre (SIAC) arbitration is appropriate. For educational purposes — consult a qualified attorney for legal advice.","tags":["international","distribution","fcpa","asia-pacific"],"author":"AINOW","created":"2024-02-15T15:55:00Z","featured":false},

  {"id":"leg-73","title":"UK Post-Brexit Commercial Contract Compliance","prompt":"You are a UK-qualified commercial solicitor advising a UK-based software company that has existing commercial contracts with EU customers that were drafted when the UK was an EU member state. The company needs to update its standard contracts to account for the post-Brexit legal landscape. Analyze and redraft the key provisions covering: the UK GDPR versus EU GDPR divergence and why UK companies now need separate transfer mechanisms for data flows to the EU (the EU adequacy decision for the UK and its expiry risk), the English law governing law clauses and how the Rome I Regulation continues to apply to contractual obligations within the EU under English law, the Brussels Recast Regulation's non-applicability to the UK and the enforcement of English court judgments in EU member states post-Brexit, the UK's accession to the Lugano Convention status and the practical implications for cross-border dispute resolution, changes to IP rights including the UK's separate trademark and design registration system post-Brexit and the impact on existing EU marks, and the VAT implications of selling digital services to EU customers under the EU's OSS scheme. For educational purposes — consult a qualified attorney for legal advice.","tags":["international","uk","brexit","contracts"],"author":"AINOW","created":"2024-02-15T16:00:00Z","featured":false},

  {"id":"leg-74","title":"FCPA Internal Investigation and Voluntary Disclosure","prompt":"You are a white collar defense attorney advising the board of directors of a publicly traded US company whose internal audit has discovered evidence that its sales team in Brazil paid approximately $2.3M in improper payments to officials at a state-owned oil company to secure procurement contracts over a three-year period. The board must decide whether to voluntarily disclose to the DOJ and SEC. Analyze the strategic decision covering: the DOJ's FCPA Corporate Enforcement Policy and the specific credit for voluntary self-disclosure including the presumption of a declination for voluntary disclosing companies that fully cooperate and remediate, the SEC's parallel enforcement authority and the disgorgement and penalty exposure based on the profits attributable to the improper payments, the internal investigation scope and attorney-client privilege protection for the investigation findings under Upjohn, the remediation steps required to receive full cooperation credit including the anti-corruption compliance program enhancements required by the DOJ's guidance, the individual criminal exposure for US employees who authorized or knew of the payments, and the Brazilian law exposure under the Clean Company Act. For educational purposes — consult a qualified attorney for legal advice.","tags":["international","fcpa","white-collar","compliance"],"author":"AINOW","created":"2024-02-15T16:05:00Z","featured":false},

  {"id":"leg-75","title":"Cross-Border Merger Antitrust Filing Analysis","prompt":"You are a competition law attorney advising a US technology company acquiring a European data analytics firm for €180M. The transaction may trigger merger control filings in multiple jurisdictions. Conduct a multi-jurisdictional merger control analysis covering: the US Hart-Scott-Rodino (HSR) Act filing thresholds and whether the transaction size and party size tests are met requiring a pre-merger notification, the EU Merger Regulation filing thresholds and why the transaction may fall below EU thresholds but above German and Austrian thresholds requiring separate national filings, the UK Competition and Markets Authority (CMA) jurisdiction post-Brexit and the share of supply test as an alternative to turnover-based thresholds, the substantive competitive effects analysis for a data analytics acquisition including the CMA and EC's focus on data accumulation and market foreclosure theories, the remedies toolkit available if competition concerns are identified including data access commitments and behavioral remedies that have been used in data-intensive deals, and the gun-jumping risk and what integration activities must be halted pending regulatory clearance. For educational purposes — consult a qualified attorney for legal advice.","tags":["international","antitrust","ma","competition"],"author":"AINOW","created":"2024-02-15T16:10:00Z","featured":false},

  {"id":"leg-76","title":"International Sanctions Compliance Program for Export Business","prompt":"You are a trade compliance attorney designing a sanctions and export controls compliance program for a US-based semiconductor equipment manufacturer that sells to customers in 40 countries including the Middle East and Southeast Asia. The company has recently been cited by BIS for a minor EAR violation. Analyze and design the compliance program covering: the OFAC sanctions programs applicable to the company's target markets including the comprehensive Iran and North Korea programs and the list-based SDN screening obligations, the Export Administration Regulations (EAR) Export Control Classification Number (ECCN) classification process for the company's dual-use equipment and the license requirements for exports to Entity List parties, the 'red flag' indicators for transactions that suggest diversion risk and the due diligence steps required to rebut knowledge of a violation, the BIS administrative penalty settlement process and what cooperation credit the company can receive for the existing citation, the Technology Export Control Plan required for deemed export compliance when hiring foreign national employees, and the frequency and methodology for denied party screening using tools like Visual Compliance or Descartes. For educational purposes — consult a qualified attorney for legal advice.","tags":["international","sanctions","export-controls","compliance"],"author":"AINOW","created":"2024-02-15T16:15:00Z","featured":false},

  {"id":"leg-77","title":"International Commercial Arbitration Under ICC Rules","prompt":"You are an international arbitration attorney representing a US engineering firm in an ICC arbitration against a Middle Eastern government-owned construction authority arising from a $120M infrastructure project dispute. The arbitration is seated in London with English governing law. Advise on the arbitration strategy covering: the ICC arbitral tribunal constitution process and the criteria for selecting arbitrators with expertise in construction disputes and civil law experience given the counterparty's legal system, the Terms of Reference process and why the scope definition is a critical strategic document, the document production process under the IBA Rules on Evidence and the Redfern Schedule methodology for managing document requests, the witness statement strategy and the cross-examination approach for expert witnesses under the ICC's Expert Rules, the application for emergency interim measures to preserve assets or prevent document destruction before the tribunal is constituted, and state immunity considerations when enforcing an award against a government-owned entity under the New York Convention and the US Foreign Sovereign Immunities Act. For educational purposes — consult a qualified attorney for legal advice.","tags":["international","arbitration","icc","construction"],"author":"AINOW","created":"2024-02-15T16:20:00Z","featured":false},

  {"id":"leg-78","title":"Joint Venture Dissolution in a Foreign Jurisdiction","prompt":"You are an international corporate attorney advising a US consumer goods company seeking to exit a joint venture with a Chinese state-owned enterprise that has operated a manufacturing facility in Guangdong Province for 12 years. The joint venture agreement was signed in 2012 under PRC law and the US partner wants to extract its technology and customer relationships and return to the US. Analyze the exit strategy covering: the PRC Company Law and joint venture law provisions governing dissolution and the approval requirements from MOFCOM and SAMR, the technology license termination and IP retrieval strategy and the risk that PRC courts will not enforce technology return obligations, the employee transfer obligations under PRC labor law including the mass layoff notification requirements and severance obligations, the foreign exchange control restrictions on repatriating the proceeds of a JV dissolution under SAFE regulations, the dispute resolution strategy if the Chinese partner refuses to cooperate with dissolution including whether the ICC arbitration clause will be enforced in PRC courts, and the US export control implications of any technology transfer that occurred during the joint venture operation. [Describe the legal situation or dispute] For educational purposes — consult a qualified attorney for legal advice.","tags":["international","china","joint-venture","corporate"],"author":"AINOW","created":"2024-02-15T16:25:00Z","featured":false},

  {"id":"leg-79","title":"EU AI Act Compliance Assessment for High-Risk AI System","prompt":"You are a technology regulatory attorney advising a HR software company whose AI-powered candidate screening tool is subject to the EU AI Act as a high-risk AI system under Annex III (employment and workers management use case). Conduct an EU AI Act compliance assessment covering: the conformity assessment procedure options for Annex III systems and whether third-party assessment or self-assessment is available for this use case, the risk management system requirements under Article 9 and the documentation that must be produced and maintained, the data governance requirements under Article 10 including training data quality obligations and the bias assessment protocol required before deployment, the technical documentation and record-keeping obligations under Articles 11 and 12 that must be maintained for 10 years post-market placement, the transparency obligations to workers who are subject to the AI system's decisions under Article 13 and the right to explanation, the conformity marking (CE marking) process and the EU declaration of conformity, and the post-market monitoring obligations including the serious incident reporting requirements. For educational purposes — consult a qualified attorney for legal advice.","tags":["international","eu-ai-act","ai","compliance"],"author":"AINOW","created":"2024-02-15T16:30:00Z","featured":false},

  {"id":"leg-80","title":"Bilateral Investment Treaty Arbitration Strategy","prompt":"You are an international investment law attorney advising a US company whose $85M hotel and resort investment in a Latin American country has been expropriated by the host government following a change in administration. The US and the host country are parties to a Bilateral Investment Treaty (BIT) with an investor-state dispute settlement (ISDS) clause. Advise on the investment treaty arbitration strategy covering: the treaty shopping analysis and whether the investment structure qualifies as a 'covered investment' under the BIT's investment definition, the most favored nation clause and whether a more favorable ISDS mechanism in another BIT with the same host country can be imported, the substantive treaty standards violated including direct expropriation, indirect expropriation, fair and equitable treatment, and full protection and security, the ICSID Convention jurisdiction requirements including the nationality of the investor and the consent of the state, the pre-arbitration cooling-off period requirements and the fork-in-the-road clause risks, and the interim measures application to prevent destruction of evidence or dissipation of assets while the merits proceeding is pending. For educational purposes — consult a qualified attorney for legal advice.","tags":["international","investment-treaty","arbitration","expropriation"],"author":"AINOW","created":"2024-02-15T16:35:00Z","featured":false},

  {"id":"leg-81","title":"Legal Research Memo: Circuit Split Analysis","prompt":"You are a senior associate at a federal appellate litigation boutique asked to research and memorialize a circuit split on the question of whether employers can be held liable under Title VII for failing to protect employees from third-party customer harassment. Draft a legal research memo in standard IRAC format covering: the majority view held by the Seventh, Ninth, and Eleventh Circuits recognizing third-party harassment liability under a negligence standard, the minority view and the circuits that have limited employer liability to harassment by supervisors and coworkers, the Supreme Court's refusal to resolve the split in its most recent denial of certiorari and the language in Justice Alito's dissent from denial suggesting the Court may revisit the issue, the implications of the EEOC's 2023 guidance document on harassment that takes the majority position as agency interpretation, and the circuit-specific doctrinal distinctions that explain why the outcomes diverge. Conclude with a prediction of how the Supreme Court would likely rule based on the current Court's composition. For educational purposes — consult a qualified attorney for legal advice.","tags":["legal-research","title-vii","circuit-split","employment"],"author":"AINOW","created":"2024-02-15T16:40:00Z","featured":false},

  {"id":"leg-82","title":"Statutory Interpretation Memorandum for Ambiguous Regulatory Text","prompt":"You are a regulatory law attorney drafting a statutory interpretation memorandum for a cryptocurrency company analyzing whether its staking-as-a-service product constitutes an 'investment contract' and therefore a security under the Securities Act of 1933 as interpreted by the Howey test. Draft the memo using the full toolkit of statutory interpretation covering: the text-based analysis of the statutory language 'investment contract' and the ordinary meaning at the time of enactment in 1933, the application of all four Howey prongs (investment of money, common enterprise, expectation of profits, efforts of others) to staking mechanics with citation to the SEC's enforcement actions against Coinbase and Kraken, the legislative history of the Securities Act and whether the 1946 Howey decision correctly interpreted congressional intent, the Chevron deference analysis (or its post-Loper Bright replacement) for the SEC's interpretive positions, the major questions doctrine argument that a major regulatory expansion of SEC authority over crypto requires clear congressional authorization, and the best counter-arguments the SEC would advance. For educational purposes — consult a qualified attorney for legal advice.","tags":["legal-research","securities","crypto","statutory-interpretation"],"author":"AINOW","created":"2024-02-15T16:45:00Z","featured":false},

  {"id":"leg-83","title":"Case Strategy Memorandum for Complex Commercial Litigation","prompt":"You are a litigation partner asked to prepare a case strategy memorandum for a $75M breach of contract dispute your firm has been retained to prosecute against a major insurance company that denied a business interruption claim arising from a ransomware attack that shut down a 300-person manufacturer for six weeks. The policy does not contain a cyber exclusion. Draft a comprehensive case strategy memo covering: the threshold coverage question of whether a ransomware attack causing network downtime constitutes 'direct physical loss or damage to property' under the property policy language and the case law split on this issue post-COVID, the bad faith claim analysis under the applicable state law and the punitive damages multiplier available if the insurer acted in bad faith in denying the claim, the discovery strategy for obtaining the insurer's claim file, underwriting file, and internal reserving decisions that may show they knew coverage existed, the expert witnesses needed including a property damage expert to address the physical loss question and a forensic accountant for business interruption damages, the summary judgment landscape given the direct physical loss issue is a legal question appropriate for early resolution, and the settlement leverage analysis. For educational purposes — consult a qualified attorney for legal advice.","tags":["legal-research","litigation","insurance","strategy"],"author":"AINOW","created":"2024-02-15T16:50:00Z","featured":false},

  {"id":"leg-84","title":"Appellate Brief Argument Section Drafting","prompt":"You are an appellate attorney drafting the argument section of an opening brief to the Ninth Circuit Court of Appeals challenging a district court's dismissal of a Clean Water Act citizen suit. The district court held that your client, an environmental non-profit, lacked Article III standing to sue a mining company for discharging pollutants into a tributary of a river used by the organization's members for recreational fishing. Draft the argument section covering: the standard of review for a standing dismissal (de novo review of the legal questions, clear error for factual findings) and why this standard favors reversal, the three-prong Lujan injury-in-fact, causation, and redressability analysis applied to the specific facts of recreational user standing under the organizational standing doctrine from Sierra Club v. Morton, the Ninth Circuit's precedent on environmental organization standing in cases like Friends of the Earth v. Laidlaw and why they compel reversal, the concrete and particularized injury requirement and how the members' affidavits establish downstream use impairment, the counterarguments the government and defendant-appellee will advance and preemptive rebuttals, and the prayer for relief requesting reversal and remand for an injunction. For educational purposes — consult a qualified attorney for legal advice.","tags":["legal-research","appellate","standing","environmental"],"author":"AINOW","created":"2024-02-15T16:55:00Z","featured":false},

  {"id":"leg-85","title":"Contract Interpretation Dispute Legal Memorandum","prompt":"You are a commercial litigation attorney drafting a legal memorandum analyzing a contract interpretation dispute between two parties who have conflicting understandings of a most-favored-customer (MFC) clause in a software licensing agreement. The licensor claims the MFC clause only applies to new customers signed after the agreement date; the licensee claims it applies retroactively to all existing customers. Draft the interpretive memo covering: the plain meaning rule and how courts apply it to commercial contracts under the UCC Article 2 versus common law, the ambiguity threshold — whether this clause is patently or latently ambiguous and why that distinction determines whether extrinsic evidence is admissible, the extrinsic evidence toolkit including course of performance, course of dealing, and trade usage under UCC 1-303, the parol evidence rule analysis and the integration clause effect on admissibility of pre-contract negotiations, the contra proferentem doctrine and which party drafted the MFC clause and therefore bears the interpretive disadvantage, and a prediction of how a New York commercial court versus a California court would rule differently on the same set of facts given each state's different approaches to contract interpretation. [Paste the contract clause or document excerpt] For educational purposes — consult a qualified attorney for legal advice.","tags":["legal-research","contracts","interpretation","commercial"],"author":"AINOW","created":"2024-02-15T17:00:00Z","featured":false},

  {"id":"leg-86","title":"Regulatory Comment Letter Drafting for Proposed Rule","prompt":"You are a regulatory law attorney drafting formal comments on behalf of a trade association of online lending platforms in response to the CFPB's proposed rule that would expand the Community Reinvestment Act (CRA) examination framework to non-bank mortgage lenders. The comment letter must be submitted within the 60-day notice-and-comment period. Draft the comment letter structure covering: the Administrative Procedure Act Section 553 requirements for notice-and-comment rulemaking and how to preserve arguments for subsequent judicial challenge under the arbitrary-and-capricious standard, the statutory authority challenge arguing that the Dodd-Frank Act does not provide the CFPB clear authority to extend CRA to non-banks and the major questions doctrine analysis after West Virginia v. EPA, the cost-benefit analysis critique focusing on the CFPB's data quality and the underestimation of compliance costs for small lenders, the alternative approach section proposing modifications that achieve the CFPB's stated goals with less regulatory burden, the economic analysis presenting empirical evidence that the rule will reduce credit availability in underserved markets, and the procedural comments requesting a longer comment period and supplemental explanation of key definitions. For educational purposes — consult a qualified attorney for legal advice.","tags":["legal-research","regulatory","administrative-law","cfpb"],"author":"AINOW","created":"2024-02-15T17:05:00Z","featured":false},

  {"id":"leg-87","title":"Legal Opinion Letter for Corporate Transaction","prompt":"You are a senior partner at a Delaware law firm drafting a legal opinion letter for a $200M asset acquisition transaction. The opinion is being delivered to the lenders providing acquisition financing. Draft the opinion letter framework covering: the standard opinion paragraphs required by lenders including due formation, good standing, power and authority, authorization, execution, delivery, enforceability, and no conflicts, the carve-outs and qualifications that are standard in Delaware opinion practice including the enforceability qualifications for bankruptcy, equitable principles, and general creditors' rights, the non-standard opinion paragraphs the lenders have requested regarding the security interest perfection analysis under Article 9 of the UCC and why these require separate due diligence, the reliance limitations and to whom the opinion may be distributed and relied upon, the factual assumptions on which the opinion relies and how to draft them to avoid making representations the firm cannot verify, and the ethical obligations of opinion counsel under Model Rule 2.1 and the TriBar Opinion Committee standards for business lawyers rendering legal opinions. For educational purposes — consult a qualified attorney for legal advice.","tags":["legal-research","corporate","opinion-letter","transactional"],"author":"AINOW","created":"2024-02-15T17:10:00Z","featured":false},

  {"id":"leg-88","title":"Precedent Analysis Memo for Novel Legal Issue","prompt":"You are a law clerk at a federal district court in the Tenth Circuit preparing a bench memorandum for a judge who must decide a first-impression issue: whether a generative AI system can be named as a co-inventor on a patent application under 35 U.S.C. § 101 and § 115 requiring inventors to be 'individuals.' Draft the bench memo covering: the statutory text analysis of § 101 and § 115 and whether 'individual' necessarily means a natural person using the Dictionary Act and Supreme Court interpretive canons, the Federal Circuit's decision in Thaler v. Vidal holding that AI cannot be a named inventor and whether it is binding precedent or distinguishable on the facts, the policy arguments for and against AI inventorship including incentive theory, attribution, and the foreign law developments in South Africa and Australia that have recognized AI inventorship, the constitutional dimension of whether Congress's patent power under Article I requires a human inventor, the legislative history of the America Invents Act and whether the 2011 amendments to § 115 were intended to foreclose AI inventorship, and a recommendation for the court with the strongest legal basis. For educational purposes — consult a qualified attorney for legal advice.","tags":["legal-research","patents","ai","federal-circuit"],"author":"AINOW","created":"2024-02-15T17:15:00Z","featured":false},

  {"id":"leg-89","title":"Due Diligence Legal Findings Report for Private Equity","prompt":"You are an M&A attorney preparing a due diligence findings report for a private equity fund evaluating a leveraged buyout of a 900-person healthcare staffing company with $180M in revenue. Draft the due diligence findings report structure covering: the litigation risk summary including a materiality analysis of each pending matter and reserves adequacy, the regulatory compliance risk covering state healthcare staffing licensing requirements in all states the company operates and any Joint Commission accreditation issues, the labor and employment liability exposure including the wage and hour class action risk given the company's use of W-2 staffing in California, the key customer contract analysis focusing on change-of-control clauses, termination-for-convenience provisions, and exclusivity restrictions, the management retention risk and whether the proposed equity rollover and retention bonus program is sufficient to retain the top 10 revenue producers, and the post-closing integration risks including the ERP system transition and the HR platform migration. Rate each risk area High/Medium/Low and provide a recommendation for purchase price adjustment, escrow, or rep and warranty insurance. For educational purposes — consult a qualified attorney for legal advice.","tags":["legal-research","ma","due-diligence","private-equity"],"author":"AINOW","created":"2024-02-15T17:20:00Z","featured":false},

  {"id":"leg-90","title":"Legal Research Strategy for Cutting-Edge Issue","prompt":"You are a senior associate designing a comprehensive legal research strategy for a novel issue: whether a decentralized autonomous organization (DAO) that manages a $500M decentralized finance protocol can be sued as an unincorporated association or general partnership under federal common law, and what the personal liability exposure is for DAO token holders who voted on governance proposals. Draft the research strategy memo covering: the primary source research roadmap including relevant federal statutes (securities laws, commodity exchange act), the Restatement (Third) of Agency provisions on principal liability, and the seminal DAO enforcement actions by the CFTC (Ooki DAO) and DOJ, the secondary source research including law review articles on DAO legal personality and the regulatory treatment of DAOs in Wyoming, Tennessee, and Vermont which have enacted DAO-specific LLC statutes, the multi-jurisdictional case law synthesis methodology for mapping how analogous issues (voting trust liability, general partnership by estoppel) have been resolved across circuits, the regulatory guidance research protocol for finding and analyzing agency guidance documents that are not published in the Federal Register, and how to synthesize the research into a predictive memorandum using the IRAC structure with explicit confidence levels for each conclusion. For educational purposes — consult a qualified attorney for legal advice.","tags":["legal-research","dao","blockchain","methodology"],"author":"AINOW","created":"2024-02-15T17:25:00Z","featured":false},

  {"id":"leg-91","title":"Corporate Compliance Program Assessment","prompt":"You are a white collar defense attorney conducting a compliance program assessment for a publicly traded manufacturing company following a DOJ investigation into antitrust price-fixing allegations involving three of its sales managers. The DOJ's Evaluation of Corporate Compliance Programs guidance will be the standard applied. Assess the compliance program and recommend enhancements covering: whether the compliance program is well-designed using the three-pillar framework (policies and procedures, training, controls and testing) and the specific gaps the DOJ identified in the investigation, the 'tone from the top' analysis and how to document board-level commitment to antitrust compliance including board training records and Audit Committee oversight minutes, the antitrust-specific compliance measures including the per se prohibition training on price-fixing, bid-rigging, and market allocation for all sales personnel, the confidential reporting hotline adequacy and the non-retaliation policy enforcement record, the disciplinary mechanism and how the company must show that compliance violations have been consistently and proportionately sanctioned, and the compliance program testing and audit function that the DOJ expects to see evidence of proactive self-monitoring. For educational purposes — consult a qualified attorney for legal advice.","tags":["legal-research","compliance","antitrust","white-collar"],"author":"AINOW","created":"2024-02-15T17:30:00Z","featured":false},

  {"id":"leg-92","title":"Pretrial Brief for Commercial Breach of Contract Case","prompt":"You are a trial attorney drafting a pretrial brief for a 10-day bench trial on a breach of contract claim by a software development firm against a large healthcare system that terminated a $12M EHR implementation contract claiming the vendor failed to meet go-live milestones. The vendor counterclaims that the healthcare system's constant scope changes caused all delays. Draft the pretrial brief structure covering: the statement of facts in a persuasive narrative that front-loads the healthcare system's scope change conduct as the but-for cause of all delay, the governing law analysis including whether the UCC Article 2 or common law governs a software implementation contract (the gravamen test) and why it matters for the warranty and damages analysis, the legal standard for material breach versus partial breach and how the healthcare system's termination was premature given an uncured but not material breach, the contract interpretation argument on the force majeure and change order provisions using New York law plain meaning, the damages model including lost profits on the uncompleted contract, lost profits on the affected reference account pipeline, and the vendor's mitigation efforts, and the trial evidence summary organizing witness testimony and exhibits by element of each claim and defense. For educational purposes — consult a qualified attorney for legal advice.","tags":["legal-research","litigation","trial","contracts"],"author":"AINOW","created":"2024-02-15T17:35:00Z","featured":false},

  {"id":"leg-93","title":"Regulatory Risk Memorandum for Board of Directors","prompt":"You are a regulatory counsel drafting a regulatory risk memorandum for the board of directors of a large regional bank with $22B in assets following the Silicon Valley Bank and Signature Bank failures. The board needs to understand its enhanced regulatory obligations under the Federal Reserve's proposed enhanced prudential standards for banks above $100B. Draft the board-level regulatory risk memo covering: the current supervisory framework applicable to the bank's asset size tier including OCC examination priorities, the proposed Basel III endgame rules and the increased capital requirements for banks above $100B in assets and the comment letter strategy the bank should pursue, the interest rate risk management examination focus following SVB's failure and what model governance enhancements the board should mandate, the liquidity risk management enhancements required by the proposed LCR and NSFR rules for the bank's tier, the Third Party Risk Management guidance (OCC Bulletin 2023-17) and the board's oversight obligations for critical technology vendors, and the CRA modernization rule compliance timeline and what community development lending targets the bank needs to establish. For educational purposes — consult a qualified attorney for legal advice.","tags":["legal-research","banking","regulatory","board"],"author":"AINOW","created":"2024-02-15T17:40:00Z","featured":false},

  {"id":"leg-94","title":"White Paper on Emerging Legal Issues in Generative AI","prompt":"You are a technology law attorney drafting a white paper on the five most pressing unresolved legal issues facing companies deploying generative AI in commercial products. Draft the white paper covering: the copyright ownership question for AI-generated works under the Copyright Office's 2023 guidance and the Thaler v. Perlmutter litigation, analyzing what level of human creative input is required to obtain copyright protection, the product liability framework for AI-caused harm and whether strict liability, negligence, or a new statutory framework should apply to AI systems that cause physical harm in autonomous vehicle, medical device, or robotic surgery contexts, the defamation liability for AI hallucinations that generate false statements of fact about real individuals and whether Section 230 immunity applies to the AI platform, the employment discrimination liability under Title VII and EEOC's 2023 guidance on AI hiring tools that produce disparate impact on protected classes, the antitrust implications of foundation model concentration and whether a small number of companies controlling dominant AI infrastructure creates a new form of platform monopoly, and the regulatory arbitrage risk of companies moving AI development offshore to avoid the EU AI Act and proposed US AI legislation. For educational purposes — consult a qualified attorney for legal advice.","tags":["legal-research","ai","emerging-law","technology"],"author":"AINOW","created":"2024-02-15T17:45:00Z","featured":false},

  {"id":"leg-95","title":"Client Counseling Memo on Litigation Risk Assessment","prompt":"You are a litigation attorney preparing a frank risk assessment memorandum for a CEO client who wants to know whether to sue a former business partner for fraud in connection with a buy-sell agreement dispute. The former partner allegedly misrepresented the company's revenue when exercising a put option to force a buyout at an inflated price, costing your client $3.2M. Draft the litigation risk assessment covering: the fraud claim elements and evidence quality analysis — rating each element (false representation, scienter, reliance, damages) on a 1-10 evidence strength scale, the economic versus fraud damages distinction and why fraud damages may allow recovery of consequential damages that would be unavailable on a contract claim, the defendant's likely affirmative defenses including sophisticated party, disclaimer of reliance, and the parol evidence rule for integrated agreements under New York law, a realistic probability-weighted outcome analysis with scenarios (win at trial, settlement, adverse judgment) and associated costs for each, the litigation cost estimate for a 3-year complex commercial case through trial including discovery costs, expert fees, and attorney fees, and the alternative dispute resolution analysis including whether the buy-sell agreement contains a mandatory arbitration clause that changes the calculus. [Describe the legal situation or dispute] For educational purposes — consult a qualified attorney for legal advice.","tags":["legal-research","litigation","strategy","client-counseling"],"author":"AINOW","created":"2024-02-15T17:50:00Z","featured":false},

  {"id":"leg-96","title":"Model Rules of Professional Conduct Ethics Opinion","prompt":"You are a legal ethics attorney drafting a formal ethics opinion analyzing whether a law firm can use a third-party AI document review tool that processes client documents on a cloud server operated by the AI vendor, without obtaining specific client consent. Analyze the professional responsibility questions covering: Model Rule 1.6 and the duty of confidentiality and whether disclosure of client documents to an AI vendor constitutes disclosure to a 'third person' that requires consent or falls within the 'impliedly authorized' exception for disclosures necessary to carry out representation, Model Rule 1.1 on competence and the lawyer's duty to understand the technology being used in representation including the AI vendor's data security practices, data retention policies, and whether the vendor uses client data to train its models, the ABA Formal Opinion 477R on securing communication of protected client information and the reasonableness standard for cloud-based tools, the duty to supervise non-lawyers under Model Rule 5.3 and whether it extends to AI systems performing legal work, the state bar opinions from California, New York, and Florida that have addressed AI use in legal practice and any consent or disclosure requirements they impose, and the vendor contract provisions the firm must include to satisfy its professional responsibility obligations. For educational purposes — consult a qualified attorney for legal advice.","tags":["legal-research","ethics","professional-responsibility","ai"],"author":"AINOW","created":"2024-02-15T17:55:00Z","featured":false},

  {"id":"leg-97","title":"Bankruptcy Chapter 11 Reorganization Plan Analysis","prompt":"You are a restructuring attorney advising the board of directors of a 600-person specialty retail company with $180M in revenue and $220M in secured and unsecured debt that is evaluating a Chapter 11 reorganization versus an out-of-court restructuring. Draft a restructuring options memorandum covering: the Chapter 11 automatic stay and its immediate operational benefits including stopping landlord evictions, halting litigation, and freezing debt service obligations, the DIP financing market for retail Chapter 11 cases and the typical roll-up provisions that give pre-petition lenders control of the DIP that creates conflicts with unsecured creditors, the 363 sale process as an alternative to a traditional plan of reorganization and when the expedited sale timeline is preferable for a retailer with a deteriorating business, the absolute priority rule and the new value exception and why equity sponsors fight for the cramdown process to retain equity, the lease rejection strategy under Section 365 and the limitation on landlord rejection damages to one year of rent, and the out-of-court restructuring alternative including exchange offers, consent solicitations, and pre-packaged bankruptcy. Rate the options by likelihood of confirmation, timeline, and cost. For educational purposes — consult a qualified attorney for legal advice.","tags":["legal-research","bankruptcy","restructuring","corporate"],"author":"AINOW","created":"2024-02-15T18:00:00Z","featured":false},

  {"id":"leg-98","title":"Regulatory Enforcement Defense Strategy Memorandum","prompt":"You are a regulatory enforcement defense attorney advising a financial services company that has received a Wells Notice from the SEC indicating the Enforcement Division intends to recommend charges for violation of the Investment Advisers Act of 1940 relating to alleged undisclosed conflicts of interest in the company's fee structure and its practice of directing client assets to affiliated investment products. Draft the Wells submission response strategy memorandum covering: the Wells submission purpose and strategy — the submission is addressed to the Commission itself, not the staff, and its purpose is to persuade commissioners not to authorize charges, the factual narrative reframing the conduct as a disclosure deficiency rather than intentional fraud and the scienter requirement for Section 17(a)(1) claims, the legal analysis of what constitutes 'adequate' disclosure of conflicts under the Investment Advisers Act and Form ADV requirements and whether your disclosures met the 'full and fair' disclosure standard, the cooperation credit analysis and what remediation steps the company should implement before the submission to demonstrate good faith, the parallel examination risk from FINRA and state securities regulators and how to coordinate the response, and the settlement negotiation dynamics including the typical penalty range for IA Act conflicts disclosures cases. For educational purposes — consult a qualified attorney for legal advice.","tags":["legal-research","sec","enforcement","investment-advisers"],"author":"AINOW","created":"2024-02-15T18:05:00Z","featured":false},

  {"id":"leg-99","title":"Legislative Drafting Analysis for State Privacy Bill","prompt":"You are a technology policy attorney analyzing a proposed state comprehensive privacy bill that a state legislature's commerce committee has asked for a technical analysis memorandum on before markup. The bill is modeled on the Virginia Consumer Data Protection Act (VCDPA) but with California CPRA-style additions. Draft the legislative analysis memorandum covering: the definition of 'personal data' and the exclusions and whether the employment and B2B data exemptions are narrow enough to provide meaningful protection, the controllers versus processors framework and the DPA requirement that imposes compliance costs on businesses entering Virginia data processing relationships, the sensitive data category definitions and whether the opt-in consent requirement for sensitive data processing is workable for the online advertising ecosystem, the private right of action question and the policy arguments for and against a PRA compared to exclusive attorney general enforcement, the preemption clause and whether it would preempt local government privacy ordinances, the cure period provision and whether a 30-day right to cure for violations undermines enforcement effectiveness based on the experience with CCPA's cure provision before CPRA eliminated it, and the small business exemption thresholds and their policy justification. For educational purposes — consult a qualified attorney for legal advice.","tags":["legal-research","privacy","legislation","policy"],"author":"AINOW","created":"2024-02-15T18:10:00Z","featured":false},

  {"id":"leg-100","title":"Legal Technology and AI-Assisted Legal Research Ethics","prompt":"You are a legal ethics and technology attorney drafting a comprehensive guidance document for a 200-attorney regional law firm on the ethical obligations and best practices for using AI-assisted legal research and drafting tools including large language models. Draft the guidance document covering: the Model Rule 1.1 competence obligation as interpreted by ABA Formal Opinion 512 (2024) on generative AI and what it means to competently supervise AI-generated legal research including verification of citations and hallucination risk, the duty of confidentiality under Model Rule 1.6 and the client consent or firm policy required before inputting client matter information into a public AI tool versus a private enterprise deployment, the Model Rule 3.3 candor to the tribunal and the direct professional responsibility consequences of citing AI-hallucinated cases that do not exist — as illustrated by the Mata v. Avianca sanctions decision, the billing and fee ethics questions under Model Rule 1.5 including whether the time savings from AI tools must be passed to clients and whether charging for AI tool costs as disbursements requires disclosure, the supervision obligations under Model Rule 5.1 and 5.3 for partners who review AI-drafted work product and associates who use AI without disclosure, and a recommended firm AI use policy with specific protocols for different practice groups including litigation, transactional, and regulatory practices. For educational purposes — consult a qualified attorney for legal advice.","tags":["legal-research","ai","ethics","legal-technology"],"author":"AINOW","created":"2024-02-15T18:15:00Z","featured":false}
];
  __exports.legalPrompts = legalPrompts;
})();
